  ui_story_5057_50570101_21_dialog_content = "Probablemente sea imposible atrapar a la Diosa Denuo con esto.",
  ui_story_5057_50570101_22_dialog_content = "Jaja, es, eh... definitivamente es imposible atrapar a la Diosa Denuo con esto.",
  ui_story_5057_50570101_23_dialog_content = "Creo que va a ser un desafío bastante grande con el equipo que tenemos ahora mismo.",
  ui_story_5057_50570101_24_dialog_content = "Pero tú eres el famoso Caelestite, ¿cierto? Gasté mucho dinero para contratarte.",
  ui_story_5057_50570101_25_dialog_content = "Uh, sí, cierto. Ya que eres el empleador, haré mi mejor esfuerzo.",
  ui_story_5057_50570101_26_dialog_content = "Pero, ¿por qué Diosa Denuo?",
  ui_story_5057_50570101_27_dialog_content = "Ejem, ¿todavía recuerdas el eslogan original para la promoción del complejo turístico?",
  ui_story_5057_50570101_28_dialog_content = "\"¿Quieres cumplir tu mayor deseo? ¡Ven a buscar a la afortunada Diosa Denuo!\"",
  ui_story_5057_50570101_29_dialog_content = "¿Es así?",
  ui_story_5057_50570101_30_dialog_content = "Sí, exactamente.",
  ui_story_5057_50570101_31_dialog_content = "Eso es porque lo has estado repitiendo en mis oídos...",
  ui_story_5057_50570101_32_dialog_content = "Sí, y me enorgullece verte comprometiéndote a memorizar el lema.",
  ui_story_5057_50570101_33_dialog_content = "Seguro seguro. No nos desviemos.",
  ui_story_5057_50570101_34_dialog_content = "Oh, cierto... Entonces, pasó mucho antes, como sabes.",
  ui_story_5057_50570101_35_dialog_content = "De repente, comenzó un rumor de que la Diosa Denuo había abandonado el complejo turístico.",
  ui_story_5057_50570101_36_dialog_content = "Eh, ¿no fue publicidad engañosa desde el principio?",
  ui_story_5057_50570101_37_dialog_content = "¡No es publicidad engañosa si no puedes demostrarlo!",
  ui_story_5057_50570101_38_dialog_content = "Pero si hay un rumor que dice que es falso, debo presentar pruebas en contrario.",
  ui_story_5057_50570101_39_dialog_content = "¿Así que tu plan es atrapar a la Diosa Denuo?",
  ui_story_5057_50570101_40_dialog_content = "Por supuesto que en realidad no la vamos a atrapar, pero al menos conseguiremos una foto.",
  ui_story_5057_50570101_41_option_content = "Lo haré lo mejor que pueda.",
  ui_story_5057_50570101_42_dialog_content = "Bueno. No estoy seguro de poder hacerlo, pero haré lo mejor que pueda.",
  ui_story_5057_50570101_43_dialog_content = "¡Maravilloso, ese es mi asistente confiable!",
  ui_story_5057_50570101_44_option_content = "Creo que es difícil.",
  ui_story_5057_50570101_45_dialog_content = "Probablemente sea imposible con una red como esta.",
  ui_story_5057_50570101_46_dialog_content = "¡Oye, no te rindas tan fácilmente! Te daré un aumento si atrapas uno.",
  ui_story_5057_50570101_X46_dialog_content = "No te preocupes, no te estoy pidiendo que realmente la atrapes, así que relájate.",
  ui_story_5057_50570101_X47_dialog_content = "¡Solo mantén a la diosa tranquila y quieta el tiempo suficiente para que yo tome una foto!",
  ui_story_5057_50570101_47_dialog_content = "¡Ah! El aire aquí es súper relajante.",
  ui_story_5057_50570101_48_dialog_content = "Sí, es como si pudiera limpiar y actualizar tu alma.",
  ui_story_5057_50570101_49_dialog_content = "Exactamente, una evaluación muy objetiva y pertinente.",
  ui_story_5057_50570101_50_dialog_content = "No perdamos más tiempo y comencemos la búsqueda. ¡Pon tus habilidades psíquicas en buen uso!",
  ui_story_5057_50570101_51_dialog_content = "¿Por qué siento que ahora soy un sabueso?",
  ui_story_5057_50570101_52_dialog_content = "Tú puedes hacerlo, Caelestita.",
  ui_story_5057_50570101_53_dialog_content = "<color=#e8d9bb>Unas horas después</color>",
  ui_story_5057_50570101_54_dialog_content = "O-Olvidalo, no puedo conseguir pistas...",
  ui_story_5057_50570101_55_dialog_content = "He estado usando mi poder mental y me ha freído el cerebro...",
  ui_story_5057_50570101_56_dialog_content = "Tomemos un descanso entonces. Yo también me estoy cansando un poco de caminar con estos tacones altos.",
  ui_story_5057_50570101_57_dialog_content = "Estoy bastante seguro de que te recordé cambiar a un par de zapatos más cómodos.",
  ui_story_5057_50570101_58_dialog_content = "Sí, pero tenía tanta prisa que olvidé hacerlo.",
  ui_story_5057_50570101_59_dialog_content = "Pero como una verdadera dama, puedo atravesar cualquier terreno difícil como si fuera un suave piso de mármol con tacones.",
  ui_story_5057_50570101_60_dialog_content = "Eso es muy impresionante...",
  ui_story_5057_50570101_61_dialog_content = "Eh, ¿por qué me estás mirando...?",
  ui_story_5057_50570101_62_dialog_content = "No te muevas, PlayerName.",
  ui_story_5057_50570101_63_dialog_content = "Veo algo que se parece a la Diosa Denuo detrás de ti.",
  ui_story_5057_50570101_64_dialog_content = "A-¿Estás seguro? ¿Cómo es que no puedo sentirlo?",
  ui_story_5057_50570101_65_dialog_content = "No muy seguro aún. Necesito acercarme más.",
  ui_story_5057_50570101_66_dialog_content = "¡Oye, es peligroso por ese camino!",
  ui_story_5057_50570101_67_dialog_content = "¡Se está escapando!",
  ui_story_5057_50570101_68_dialog_content = "¡Se está escapando! ¡Realmente parece la Diosa Denuo!",
  ui_story_5057_50570101_69_dialog_content = "¡Cuidado con tus pies, Lorelei!",
  ui_story_5057_50570101_70_dialog_content = "¡Uh!",
  ui_story_5057_50570101_71_dialog_content = "¿Estás bien, Lorelei?",
  ui_story_5057_50570101_72_dialog_content = "S-Sí, estoy bien...",
  ui_story_5057_50570101_73_dialog_content = "Acabo de tropezar...",
  ui_story_5057_50570101_X74_dialog_content = "Creo que la cámara también se rompió...",
  ui_story_5057_50570101_74_dialog_content = "Olvídate de la cámara. ¿Estás herido?",
  ui_story_5057_50570101_75_dialog_content = "Probablemente el tobillo está torcido... también se rompió el tacón de tus zapatos.",
  ui_story_5057_50570101_76_dialog_content = "Tus calcetines y pies están sucios por pisar el barro...",
  ui_story_5057_50570101_77_dialog_content = "Lo siento, PlayerName... Debería haberte escuchado y cambiado de zapatos.",
  ui_story_5057_50570101_78_dialog_content = "<color=#e8d9bb>Ramas y arbustos rasguñaron las piernas de Lorelei, dejando pequeños rastros de sangre. Su tobillo está visiblemente torcido e hinchado.</color>",
  ui_story_5057_50570101_79_dialog_content = "No importa eso ahora. Tenemos que ir a ver si tienes algún hueso roto.",
  ui_story_5057_50570101_80_dialog_content = "Seguro... regresemos. ¿Te importaría encontrar un tronco para que lo use como muleta?",
  ui_story_5057_50570101_81_dialog_content = "¿Qué dices? Ni siquiera puedes ponerte de pie ahora.",
  ui_story_5057_50570101_82_dialog_content = "Solo va a empeorar la lesión si intentas caminar de regreso.",
  ui_story_5057_50570101_83_dialog_content = "<color=#e8d9bb>Doy la espalda a Lorelei y me agacho.</color>",
  ui_story_5057_50570101_84_dialog_content = "Vamos. Te llevaré en mi espalda.",
  ui_story_5057_50570101_85_dialog_content = "Soy un adulto, puedo caminar por mi cuenta. Solo los niños necesitan ser cargados en la espalda de alguien...",
  ui_story_5057_50570101_86_dialog_content = "Pero creo que las personas que fingen ser adultos son realmente niños.",
  ui_story_5057_50570101_87_dialog_content = "Además, ¿no es el trabajo del jefe mandar a sus empleados?",
  ui_story_5057_50570101_88_dialog_content = "B-Bien, si insistes.",
  ui_story_5057_50570101_89_dialog_content = "<color=#e8d9bb>Con un poco de renuencia, Lorelei sube a mi espalda torpemente.</color>",
  ui_story_5057_50570101_90_dialog_content = "Está bien. Supongo que no tengo intenciones de dejar que mi dinero se desperdicie.",
  ui_story_5057_50570101_91_dialog_content = "Agárrate fuerte y regresemos.",
  ui_story_5057_50570101_92_dialog_content = "Okay...",
  ui_story_5057_50570101_93_dialog_content = "Eh...",
  ui_story_5057_50570101_94_dialog_content = "¿Si?",
  ui_story_5057_50570101_95_dialog_content = "Gracias.",
  ui_story_5057_50570101_96_dialog_content = "<color=#e8d9bb>Mientras regresamos, Lorelei se queda dormido en mi espalda, regalándome charlas extrañas y sin sentido de sus sueños todo el camino.</color>",
  ui_story_5057_50570102_1_dialog_content = "¡PlayerName!",
  ui_story_5057_50570102_2_dialog_content = "¡Ven aquí, rápido!",
  ui_story_5057_50570102_3_dialog_content = "¡Aquí vienen!",
  ui_story_5057_50570102_4_dialog_content = "¿Cómo está tu pie hoy?",
  ui_story_5057_50570102_5_dialog_content = "¡Está bien ahora! No subestimes mi habilidad para recuperarme. Por supuesto, tú también tuviste un papel en la recuperación.",
  ui_story_5057_50570102_6_dialog_content = "Sin problema. Después de todo, soy tu asistente.",
  ui_story_5057_50570102_7_dialog_content = "Even si no lo fuera, de todos modos no te dejaría a tu suerte. Eres un amigo importante para mí.",
  ui_story_5057_50570102_8_dialog_content = "Amigo... ¡Eso me recuerda!",
  ui_story_5057_50570102_9_dialog_content = "Debe haber muchas especialidades en Eraveil, ¿cierto? ¡Deberíamos ser socios comerciales!",
  ui_story_5057_50570102_10_dialog_content = "Está por debajo de ti ser mi asistente, ¿qué tal si nos asociamos?",
  ui_story_5057_50570102_11_dialog_content = "¿Cómo es que ves oportunidades de negocio en todas partes, Lorelei? Pero debo decir que eres muy bueno en eso...",
  ui_story_5057_50570102_12_dialog_content = "Oh, pasé toda la noche pensando y me di cuenta de que es demasiado difícil intentar atrapar a la Diosa Denuo con una red.",
  ui_story_5057_50570102_13_dialog_content = "¡Oh, me puse en contacto con un amigo y me prestó una cámara que es resistente al agua y a prueba de golpes!",
  ui_story_5057_50570102_14_dialog_content = "De esta manera, podemos tomar fotos cuando nos encontremos con ella.",
  ui_story_5057_50570102_15_dialog_content = "Bueno, ¿no dirían las personas que las fotos han sido manipuladas?",
  ui_story_5057_50570102_16_dialog_content = "¿Qué? ¿Cómo puedes manipular una foto?",
  ui_story_5057_50570102_17_dialog_content = "Jaja... En realidad, hay bastantes en Umbratón capaces de hacer eso.",
  ui_story_5057_50570102_18_dialog_content = "¡Pero ese no es el punto! Dejemos a la Diosa Denuo en segundo plano por hoy.",
  ui_story_5057_50570102_19_dialog_content = "¿Eh? Entonces, ¿por qué tienes tanta prisa para que esté aquí?",
  ui_story_5057_50570102_20_dialog_content = "Devolverte el favor, por supuesto, PlayerName.",
  ui_story_5057_50570102_21_dialog_content = "Pago mis deudas.",
  ui_story_5057_50570102_22_dialog_content = "Hoy todo corre por mi cuenta, ¡así que disfruta de lo que es tener el control de todo el complejo!",
  ui_story_5057_50570102_24_dialog_content = "Esta es una zona secreta del parque acuático, ¿no es maravilloso? No creo que hayas estado en este lugar antes.",
  ui_story_5057_50570102_25_dialog_content = "Sí, es mi primera vez aquí... No tenía idea de que había una zona escondida en el parque acuático.",
  ui_story_5057_50570102_26_dialog_content = "Si lo hubiera sabido antes, ¡no habría tenido que esperar en largas filas!",
  ui_story_5057_50570102_27_dialog_content = "Aunque es más espectacular que lo que está afuera, no está abierto al público.",
  ui_story_5057_50570102_28_dialog_content = "¡Lo que significa que es mi patio de recreo privado y personal!",
  ui_story_5057_50570102_29_dialog_content = "¿Así que este es el privilegio del jefe?",
  ui_story_5057_50570102_30_dialog_content = "Ajá, ¡exactamente!",
  ui_story_5057_50570102_31_dialog_content = "¿Entonces también puedo pasar el rato aquí?",
  ui_story_5057_50570102_32_dialog_content = "¡Claro! Disfruta de los toboganes y todo lo demás. Siéntete libre de beber y comer sin esperar en la fila.",
  ui_story_5057_50570102_33_dialog_content = "¡Impresionante!",
  ui_story_5057_50570102_34_dialog_content = "¡Guau, esto es genial!",
  ui_story_5057_50570102_35_dialog_content = "¡Es genial seguir montando en los toboganes de agua sin regresar a la fila!",
  ui_story_5057_50570102_36_dialog_content = "Estás un poco demasiado obsesionado con las diapositivas, PlayerName.",
  ui_story_5057_50570102_37_dialog_content = "Eso es porque nunca experimentaste la espantosamente larga fila para los toboganes allá afuera, Lorelei!",
  ui_story_5057_50570102_38_dialog_content = "Oye, ¿por qué no te cambias a un traje de baño y vienes a disfrutar esto conmigo?",
  ui_story_5057_50570102_39_dialog_content = "¡Puedo hacer eso sin cambiar!",
  ui_story_5057_50570102_40_dialog_content = "¡Mira!",
  ui_story_5057_50570102_41_dialog_content = "Entonces, ¿tu idea de diversión es salpicarme agua?",
  ui_story_5057_50570102_42_dialog_content = "¡Qué infantil! ¡No seré parte de eso!",
  ui_story_5057_50570102_43_dialog_content = "¿Infantil, dijiste? ¡Toma esto!",
  ui_story_5057_50570102_44_dialog_content = "¡Chapoteo, chapoteo!",
  ui_story_5057_50570102_45_dialog_content = "¡Chapoteo!",
  ui_story_5057_50570102_46_dialog_content = "¡Hey!",
  ui_story_5057_50570102_47_dialog_content = "Espera un minuto, ¿qué crees que estás haciendo? ¿No dijiste que es infantil?",
  ui_story_5057_50570102_48_dialog_content = "No, quiero decir que es infantil para niños.",
  ui_story_5057_50570102_49_dialog_content = "¡Pero acabo de darme cuenta de que está bien para mí! ¡Chapoteo—!",
  ui_story_5057_50570102_50_dialog_content = "Oye, ¿dónde está Lorelei?",
  ui_story_5057_50570102_51_dialog_content = "¿Dónde desapareció?",
  ui_story_5057_50570102_52_dialog_content = "¡Lamento haberte hecho esperar! Acabo de cambiarme la ropa mojada.",
  ui_story_5057_50570102_53_dialog_content = "Ah, y gracias por tu toalla también.",
  ui_story_5057_50570102_54_dialog_content = "Guau... Supongo que por eso eres el jefe. ¿Preparaste ropa de respaldo?",
  ui_story_5057_50570102_55_dialog_content = "No es de extrañar que no tuvieras que cambiarte y ponerte un traje de baño.",
  ui_story_5057_50570102_56_dialog_content = "Eres lo que vistes. Tengo tanta ropa no porque sea rico, sino porque necesito mantener una imagen profesional para mi negocio.",
  ui_story_5057_50570102_57_dialog_content = "Qué muy... razonamiento indirecto ese es.",
  ui_story_5057_50570102_58_dialog_content = "De todos modos, no hay atajos verdaderos en la vida, incluso para los ricos, pero sí existen técnicas.",
  ui_story_5057_50570102_59_dialog_content = "¿Técnicas?",
  ui_story_5057_50570102_60_dialog_content = "Ya ves, todos en el complejo parecen ser adinerados o famosos.",
  ui_story_5057_50570102_61_dialog_content = "Pero no todos son ricos... Algunos ni siquiera fueron invitados por mí.",
  ui_story_5057_50570102_62_dialog_content = "¿Qué? ¿Podrían venir aquí sin tu invitación?",
  ui_story_5057_50570102_63_dialog_content = "Sí, utilizaron sus conexiones para venir aquí y hacer más conexiones.",
  ui_story_5057_50570102_64_dialog_content = "Oh, el llamado networking, ¿cierto?",
  ui_story_5057_50570102_65_dialog_content = "¡Correcto! Eres bastante astuto.",
  ui_story_5057_50570102_66_dialog_content = "¿Entonces lo entiendes ahora? Invitarte a mi patio de juegos privado es una aprobación de nuestra conexión.",
  ui_story_5057_50570102_67_dialog_content = "¡Ya veo! No eres solo mi jefe, sino también un gran amigo. Lo sabía desde siempre.",
  ui_story_5057_50570102_68_dialog_content = "Acaso...",
  ui_story_5057_50570102_69_dialog_content = "¿Qué tengo que hacer para que me entiendas?",
  ui_story_5057_50570102_70_dialog_content = "No hablo de la amistad habitual, sino del tipo de negocio entre adultos...",
  ui_story_5057_50570102_71_dialog_content = "(¿Qué...? ¿La hice enojar?)",
  ui_story_5057_50570102_72_dialog_content = "<color=#e8d9bb>Gruñido-</color>",
  ui_story_5057_50570102_73_dialog_content = "¿Qué es eso?",
  ui_story_5057_50570102_74_dialog_content = "Lo siento, no he comido desde esta mañana.",
  ui_story_5057_50570102_75_dialog_content = "Ejem, bueno, vamos a tomar una mordida entonces.",
  ui_story_5057_50570102_76_dialog_content = "...",
  ui_story_5057_50570102_77_dialog_content = "...",
  ui_story_5057_50570102_78_dialog_content = "...",
  ui_story_5057_50570102_79_dialog_content = "(Ella ha enterrado su cara en la comida y esto se siente tan incómodo... ¿Todavía está enojada conmigo?)",
  ui_story_5057_50570102_80_dialog_content = "(Los platos están más que deliciosos, pero esta es la primera vez que la veo comer sin decir una palabra.)",
  ui_story_5057_50570102_81_dialog_content = "(¡Vaya, nos miramos a los ojos! ¡Tengo que bajar la cabeza!)",
  ui_story_5057_50570102_82_dialog_content = "Ejem, así que...",
  ui_story_5057_50570102_83_dialog_content = "La barbacoa está deliciosa... La pedí para ti. Inténtalo.",
  ui_story_5057_50570102_84_dialog_content = "<color=#e8d9bb>Terminando su frase, Lorelei se sumerge de nuevo y devora un gran bocado de carne.</color>",
  ui_story_5057_50570102_85_dialog_content = "Ah, seguro, entendido, ¡gracias!",
  ui_story_5057_50570102_86_dialog_content = "Y, Lorelei, sobre lo que pasó allí atrás...",
  ui_story_5057_50570102_87_dialog_content = "No quise decir que no quiero ser tu amigo, PlayerName.",
  ui_story_5057_50570102_88_dialog_content = "Solo quiero presentarme como una persona de negocios madura, en lugar de alguien que solo pasa el tiempo con amigos como un niño.",
  ui_story_5057_50570102_89_dialog_content = "Quiero que me quite—",
  ui_story_5057_50570102_90_option_content = "Lo entiendo.",
  ui_story_5057_50570102_91_dialog_content = "Entiendo que te esfuerzas por ganar el reconocimiento de los demás como una persona independiente.",
  ui_story_5057_50570102_92_dialog_content = "Pero... ¡aún no soy un adulto! Cuando estás conmigo, no tienes que ser maduro como un adulto. Solo relájate y sé tú mismo.",
  ui_story_5057_50570102_93_dialog_content = "Gracias, PlayerName...",
  ui_story_5057_50570102_94_option_content = "Todo está bien.",
  ui_story_5057_50570102_95_dialog_content = "Entiendo lo que quieres decir. No te preocupes, no lo tomaré a pecho. Es normal que los amigos discutan de vez en cuando!",
  ui_story_5057_50570102_96_dialog_content = "¿Todavía estás dispuesto a ser amigos conmigo? Gracias, PlayerName.",
  ui_story_5057_50570102_97_dialog_content = "<color=#e8d9bb>Después de eso, Lorelei vuelve a su ser habitual, riendo y hablando conmigo mientras disfrutamos de nuestra comida. Incluso me hace compañía y charla conmigo hasta tarde en la noche.</color>",
  ui_story_5057_50570201_1_dialog_content = "Oye, supongo que tú eres el ayudante que Lorelei mencionó, ¿verdad?",
  ui_story_5057_50570201_2_dialog_content = "Hola, supongo que Cena es la persona que necesita ayuda que mencionó Lorelei, ¿verdad?",
  ui_story_5057_50570201_3_dialog_content = "Oh, ahora me estás imitando, Celestita.",
  ui_story_5057_50570201_4_dialog_content = "¿Por qué crees? ¿Estás intentando mostrar el encanto y carisma maduro de un hombre como yo?",
  ui_story_5057_50570201_5_dialog_content = "Pero no encaja en tu categoría de edad, Celestita.",
  ui_story_5057_50570201_6_dialog_content = "¡No no es ese!",
  ui_story_5057_50570201_7_dialog_content = "¡No seas narcisista! Solo estaba siendo sarcástico.",
  ui_story_5057_50570201_8_dialog_content = "No me importa tu encanto o lo que sea.",
  ui_story_5057_50570201_9_dialog_content = "¿En serio? Hay muchas señoras que no aceptarían.",
  ui_story_5057_50570201_10_dialog_content = "Con esa actitud, tarde o temprano tendrás problemas en las relaciones.",
  ui_story_5057_50570201_11_dialog_content = "Jajaja, esa es una declaración extraña.",
  ui_story_5057_50570201_12_dialog_content = "Si me preguntas, el dolor del rechazo es un hecho de la vida que todos compartimos.",
  ui_story_5057_50570201_13_dialog_content = "La vida es corta, ¡así que disfruta!",
  ui_story_5057_50570201_14_dialog_content = "No creo eso. EveLa persona más casual tendría sentimientos y anhelaría una relación estable y armoniosa.",
  ui_story_5057_50570201_15_dialog_content = "Eso es lo que piensa la gente normal.",
  ui_story_5057_50570201_16_dialog_content = "Soy diferente, porque soy Cena.",
  ui_story_5057_50570201_17_dialog_content = "Suspiro, eso no suena encantador. Mejor vamos al grano.",
  ui_story_5057_50570201_18_dialog_content = "Como dice el refrán, \"Las cosas cambian y nada permanece igual.\"",
  ui_story_5057_50570201_19_dialog_content = "Lo que amo es deambular y probar diferentes experiencias.",
  ui_story_5057_50570201_20_dialog_content = "Las relaciones estáticas solo ponen grilletes en mis alas.",
  ui_story_5057_50570201_21_dialog_content = "Es eso así...",
  ui_story_5057_50570201_22_dialog_content = "Cuanto más intentas presentarte como un gran amante, más parece que dependes de una fachada cautivadora para evitar enfrentarte a la realidad.",
  ui_story_5057_50570201_23_dialog_content = "Ejem.",
  ui_story_5057_50570201_24_dialog_content = "Por eso ustedes, Celestitas, son un problema.",
  ui_story_5057_50570201_25_dialog_content = "El código del silencio también es una medida de adultos maduros, ya sabes. De lo contrario, no hay felicidad en la vida.",
  ui_story_5057_50570201_26_dialog_content = "Oh, estaba pensando en lo encantador que sería tener una dama encantadora que me echara una mano, convirtiendo nuestro tiempo juntos en una cita romántica.",
  ui_story_5057_50570201_27_dialog_content = "Pero ahora termino con un niño sabelotodo que puede leer mentes.",
  ui_story_5057_50570201_28_dialog_content = "Entonces, ¿qué tal si vamos a tomar una ronda o dos, tal vez disminuir un poco ese poder psíquico tuyo?",
  ui_story_5057_50570201_29_dialog_content = "Estoy aquí para trabajar, no para citas o beber como cierta persona.",
  ui_story_5057_50570201_30_dialog_content = "¿Trabajo?",
  ui_story_5057_50570201_31_dialog_content = "Todavía es mañana, ¡aún no es hora de trabajar! Vamos a divertirnos un poco primero.",
  ui_story_5057_50570201_32_dialog_content = "Sé de un lugar increíble que te dejará alucinado.",
  ui_story_5057_50570201_33_dialog_content = "El Dragón de la Noche Blanca... sin duda un lugar que me dejaría asombrado.",
  ui_story_5057_50570201_34_option_content = "¿Lo montas conmigo?",
  ui_story_5057_50570201_35_dialog_content = "Lo siento, PlayerName, no tengo interés en montar con un adolescente como tú.",
  ui_story_5057_50570201_36_dialog_content = "Entonces, ¿cuál es el acuerdo...",
  ui_story_5057_50570201_37_option_content = "¿Qué debemos hacer?",
  ui_story_5057_50570201_38_dialog_content = "Frío. Ya tengo elegido el primer objetivo.",
  ui_story_5057_50570201_39_dialog_content = "Mis ojos son tan agudos como los de un águila entrenada...",
  ui_story_5057_50570201_40_dialog_content = "Entonces, ¿qué tal esa encantadora dama allá, con un chico y una mujer?",
  ui_story_5057_50570201_41_dialog_content = "(Miro en la dirección y veo a una joven y hermosa mamá lista para hacer fila con un chico y su pequeña hermana a cuestas.)",
  ui_story_5057_50570201_42_dialog_content = "(Parecen muy felices a pesar de estar entre una multitud repleta de empujones).",
  ui_story_5057_50570201_43_dialog_content = "No vas a coquetear, ¿verdad?",
  ui_story_5057_50570201_44_dialog_content = "Tienes que ser más inteligente que eso.",
  ui_story_5057_50570201_45_dialog_content = "Hola, encantadora dama, ¿son estos tus niños? Parecían muy interesados en el juguete grande.",
  ui_story_5057_50570201_46_dialog_content = "Sí, ¡ellos dos se lo están pasando genial aquí! ¡Este complejo vacacional es realmente increíble!",
  ui_story_5057_50570201_47_dialog_content = "Como gerente del Denuo Valley Resort, ¡me alegra escuchar eso!",
  ui_story_5057_50570201_48_dialog_content = "Por lo tanto, ¡debo asegurarme de que tú y los dos jóvenes invitados disfruten al máximo el valor de su dinero!",
  ui_story_5057_50570201_49_dialog_content = "Aquí tienes tres vales VIP para ti.",
  ui_story_5057_50570201_50_dialog_content = "Oh, gerente, eres increíblemente... ¡Hey!",
  ui_story_5057_50570201_51_dialog_content = "Cuida bien de esta señora y los hermanos, PlayerName!",
  ui_story_5057_50570201_52_dialog_content = "<color=#e8d9bb>De repente, Cena empuja a los tres hacia mí y rápidamente alcanza a los dos tipos que acaban de arrebatar el bolso de la mamá.</color>",
  ui_story_5057_50570201_53_dialog_content = "¿Eh?",
  ui_story_5057_50570201_54_dialog_content = "¡Ni siquiera pienses en escaparte!",
  ui_story_5057_50570201_55_dialog_content = "<color=#e8d9bb>Cena aterriza una patada justo en la cintura del ladrón más cercano.</color>",
  ui_story_5057_50570201_56_dialog_content = "<color=#e8d9bb>El ladrón que recibió una patada sale volando y choca directamente con su compañero, y ambos caen juntos al suelo.</color>",
  ui_story_5057_50570201_57_dialog_content = "¡M-Maldita sea!",
  ui_story_5057_50570201_58_dialog_content = "Finalmente te atrapé. ¿Cómo te atreves a apuntar a la dama bajo mi vigilancia?",
  ui_story_5057_50570201_59_dialog_content = "Pero está bien, ahora tienes todo el tiempo del mundo para arrepentirte.",
  ui_story_5057_50570201_60_dialog_content = "¡Muchas gracias!",
  ui_story_5057_50570201_61_dialog_content = "Es mi deber. Valoramos la seguridad de cada huésped en el complejo turístico por encima de todo lo demás.",
  ui_story_5057_50570201_62_dialog_content = "Especialmente para una dama tan encantadora como tú.",
  ui_story_5057_50570201_63_dialog_content = "Está bien, podemos salir ahora, joven Celestita.",
  ui_story_5057_50570201_64_dialog_content = "Comparado conmigo, que una vez atrapé a un ladrón legendario como detective privado, tú lo hiciste bastante bien.",
  ui_story_5057_50570201_65_dialog_content = "¡Siéntete orgulloso de ti mismo!",
  ui_story_5057_50570201_66_dialog_content = "¿Qué? ¿Qué hice?",
  ui_story_5057_50570201_67_dialog_content = "<color=#e8d9bb>Después de eso, Cena me invita a cenar. Comemos mientras él no para de hablar sobre lo hermosa y fascinante que era esa mujer.</color>",
  ui_story_5057_50570201_68_dialog_content = "<color=#e8d9bb>Aun así, él aún no convierte ese afecto en acción, y la historia de Cena con esa dama llega a su fin así de simple.</color>",
  ui_story_5057_50570202_1_dialog_content = "Buenos días.",
  ui_story_5057_50570202_2_dialog_content = "Buenos días, Caelestita.",
  ui_story_5057_50570202_3_dialog_content = "¿Qué haces en un lugar como este tan temprano en la mañana? Te he estado buscando por todas partes.",
  ui_story_5057_50570202_4_dialog_content = "¿Dónde más estaría sino en un bar? ¿Pasar el rato en una piscina? Eso no es bueno para mi piel.",
  ui_story_5057_50570202_5_dialog_content = "Lo que quiero decir es, ¿no tienes trabajo que hacer?",
  ui_story_5057_50570202_6_dialog_content = "Has estado intentando que me relaje contigo tan descaradamente, sería un milagro que Lorelei no me descuente el salario...",
  ui_story_5057_50570202_7_dialog_content = "Jajaja, eres genial en todos los aspectos, además de ser demasiado estirado.",
  ui_story_5057_50570202_8_dialog_content = "¿No sabes vivir la vida al máximo? Con la mísera suma que Lorelei me está pagando, estoy mejor en un bar, esperando un encuentro maravilloso.",
  ui_story_5057_50570202_9_dialog_content = "Entonces, ¿cuándo aparecerá la \"ella\" que estás esperando?",
  ui_story_5057_50570202_10_dialog_content = "Oye, saca tu mente de las alcantarillas ahora, Celestita.",
  ui_story_5057_50570202_11_dialog_content = "No seas tan superficial. Simplemente hacer amigos también es maravilloso.",
  ui_story_5057_50570202_12_dialog_content = "Estoy asombrado de cómo pudiste convertirlo en mi culpa.",
  ui_story_5057_50570202_13_dialog_content = "Jajaja, eres una persona muy interesante.",
  ui_story_5057_50570202_14_dialog_content = "No te quedes ahí parado, ven. No te voy a comer vivo.",
  ui_story_5057_50570202_15_dialog_content = "No me digas que te intimida mi aire de sofisticación... ¿O simplemente no te gustan las características de demi-humano en mí?",
  ui_story_5057_50570202_16_dialog_content = "¡Eso no es cierto!",
  ui_story_5057_50570202_17_dialog_content = "Ahí tienes. Aprecio el hecho de que no tienes miedo ni siquiera de un Aurorian como yo.",
  ui_story_5057_50570202_18_dialog_content = "¿Eh? ¿Cuánto has estado bebiendo? ¿Aún sobrio?",
  ui_story_5057_50570202_19_dialog_content = "Ni una gota. Vamos al negocio.",
  ui_story_5057_50570202_20_dialog_content = "Vaya, el cambio repentino a la seriedad... No estoy acostumbrado a esto.",
  ui_story_5057_50570202_21_dialog_content = "Vamos, PlayerName, como acabo de decir, eres genial en todos los aspectos.",
  ui_story_5057_50570202_22_dialog_content = "Pero aún eres demasiado inocente en cuanto al amor y el romance. Me preocupa si podrás encontrar tu propio final feliz.",
  ui_story_5057_50570202_23_dialog_content = "No soy inocente... Even y si lo fuera, ¡no es asunto tuyo!",
  ui_story_5057_50570202_24_dialog_content = "No digas eso. Somos amigos y no puedo soportar verte tirar tu vida por la borda.",
  ui_story_5057_50570202_25_dialog_content = "Después de reflexionar toda la noche, he decidido contarte todos mis misterios.",
  ui_story_5057_50570202_26_dialog_content = "Eh, bueno.",
  ui_story_5057_50570202_27_option_content = "Puedo aceptar eso.",
  ui_story_5057_50570202_28_dialog_content = "Ese es el Caelestite que conozco. No te molestes en llamarme maestro. Vamos a entrar en ello directamente.",
  ui_story_5057_50570202_29_option_content = "No, gracias.",
  ui_story_5057_50570202_30_dialog_content = "No seas tan inflexible. Aprender nunca es algo malo.",
  ui_story_5057_50570202_31_dialog_content = "A-De acuerdo...",
  ui_story_5057_50570202_32_dialog_content = "De acuerdo, tendremos que crear un escenario...",
  ui_story_5057_50570202_33_dialog_content = "¡E-Espera!",
  ui_story_5057_50570202_34_dialog_content = "¡Ni siquiera pienses en hacerme vestirme para eso!",
  ui_story_5057_50570202_35_dialog_content = "Mmm, es una gran idea... ¿Seguro que no quieres?",
  ui_story_5057_50570202_36_dialog_content = "¡De ninguna manera!",
  ui_story_5057_50570202_37_dialog_content = "Está bien. Después de todo, tú eres mi primer alumno.",
  ui_story_5057_50570202_38_dialog_content = "Entonces, comencemos con las teorías y principios.",
  ui_story_5057_50570202_39_dialog_content = "Primero, debes tener el valor de acercarte a ella, saber cómo halagarla y hacerle saber que aprecias sus mejores cualidades.",
  ui_story_5057_50570202_40_dialog_content = "Cumplido... ¿Cómo lo hago?",
  ui_story_5057_50570202_41_dialog_content = "Prueba citas poéticas, por ejemplo.",
  ui_story_5057_50570202_42_dialog_content = "\"Eres tan hermoso y embriagador como una luna plateada\".",
  ui_story_5057_50570202_43_dialog_content = "\"Tu sonrisa rivaliza con un atardecer impresionante.\"",
  ui_story_5057_50570202_44_dialog_content = "Algo así como eso.",
  ui_story_5057_50570202_45_dialog_content = "Vale, creo que entendí la idea. ¿Y qué?",
  ui_story_5057_50570202_46_dialog_content = "El siguiente movimiento es mortal. Tienes que ser encantador como yo para lograrlo.",
  ui_story_5057_50570202_47_dialog_content = "Tú cruzas tu mirada con la de ella, con una pasión desenfrenada.",
  ui_story_5057_50570202_48_dialog_content = "Derrítela con tu mirada.",
  ui_story_5057_50570202_49_dialog_content = "Parpadea suavemente y envía señales.",
  ui_story_5057_50570202_50_dialog_content = "O si crees que eres lo suficientemente encantador, puedes lanzarle un beso.",
  ui_story_5057_50570202_51_dialog_content = "¡Nadie podría resistirse a eso!",
  ui_story_5057_50570202_52_dialog_content = "Uh, no me siento bien en este momento...",
  ui_story_5057_50570202_53_dialog_content = "Entonces, ¿sentiste cuán poderoso es?",
  ui_story_5057_50570202_54_dialog_content = "Sí...",
  ui_story_5057_50570202_55_dialog_content = "Luego viene el tercer movimiento. Debes ser resiliente o tener muy poca vergüenza.",
  ui_story_5057_50570202_56_dialog_content = "Tienes que tener el bravuconería para presumir en los momentos adecuados.",
  ui_story_5057_50570202_57_dialog_content = "Y agregar de vez en cuando frases descaradas pero divertidas hará que más personas te aprecien.",
  ui_story_5057_50570202_58_dialog_content = "Conocer a una dama como tú debe ser mi recompensa por salvar a Astra!",
  ui_story_5057_50570202_59_dialog_content = "Sí, admito que es un poco cliché, pero tienes que aprender que les encantan los cumplidos!",
  ui_story_5057_50570202_60_dialog_content = "Creo que escucharte es mi castigo por quizás haber destruido Astra en la vida anterior...",
  ui_story_5057_50570202_61_dialog_content = "Nada mal, ¡aprendes rápido!",
  ui_story_5057_50570202_62_dialog_content = "Estás cerca de graduarte ahora. Te llevaré a una prueba de campo más tarde.",
  ui_story_5057_50570202_63_dialog_content = "No puedo creer que realmente estoy aquí...",
  ui_story_5057_50570202_64_dialog_content = "Solo quería aprender algo inútil... Eso no es algo malo, ¿verdad?",
  ui_story_5057_50570202_65_dialog_content = "Entonces, ¿dónde está Cena? Llega tarde...",
  ui_story_5057_50570202_66_dialog_content = "¡PlayerName!",
  ui_story_5057_50570202_67_dialog_content = "Lo siento, llegué tarde.",
  ui_story_5057_50570202_68_dialog_content = "Lorelei me agarró para hablar de trabajo. Tuve que esforzarme mucho para escapar.",
  ui_story_5057_50570202_69_dialog_content = "No has estado esperando mucho tiempo, ¿verdad? Aquí tienes un chocolate que tomé del escritorio de Lorelei.",
  ui_story_5057_50570202_70_dialog_content = "No, acabo de llegar... Oh, gracias.",
  ui_story_5057_50570202_71_dialog_content = "Ven, PlayerName, dime en quién estás interesado entre la multitud.",
  ui_story_5057_50570202_72_dialog_content = "Eh, ¿estamos haciendo esto de verdad? No me gusta acercarme a desconocidos con esa intención en mente...",
  ui_story_5057_50570202_73_dialog_content = "No lo pienses demasiado. Solo es una práctica, no le hace daño a nadie.",
  ui_story_5057_50570202_74_dialog_content = "Pero si aún te preocupa, deberíamos abortar.",
  ui_story_5057_50570202_75_dialog_content = "Alguien que no disfrute del proceso nunca puede esperar convencer a la presa.",
  ui_story_5057_50570202_76_dialog_content = "Pero ya que estamos aquí, ¿por qué no nos divertimos y pasamos un buen rato juntos?",
  ui_story_5057_50570202_77_dialog_content = "¿Nosotros dos?",
  ui_story_5057_50570202_78_dialog_content = "Estoy bien con eso, pero tengo la sensación de que tú organizaste todo esto...",
  ui_story_5057_50570202_79_dialog_content = "¿Qué están haciendo ustedes dos aquí?",
  ui_story_5057_50570202_80_dialog_content = "¿Lorelei?",
  ui_story_5057_50570202_81_dialog_content = "Cena se fue corriendo de alegría, así que lo seguí.",
  ui_story_5057_50570202_82_dialog_content = "Estaba seguro de que estaba recogiendo niñas de nuevo. ¿Quién es la víctima esta vez?",
  ui_story_5057_50570202_83_dialog_content = "Lo entendiste mal. Solo estoy pasando el rato con PlayerName hoy.",
  ui_story_5057_50570202_84_dialog_content = "¿Pasando el rato? No intentes engañarme.",
  ui_story_5057_50570202_85_dialog_content = "Vamos, me duele mucho que mi jefe no confíe en mí.",
  ui_story_5057_50570202_86_dialog_content = "¡Regresa conmigo y deja de corromper al Caelestita!",
  ui_story_5057_50570202_87_dialog_content = "Bien, bien...",
  ui_story_5057_50570202_88_dialog_content = "Lo haremos de nuevo más tarde, PlayerName!",
  ui_story_5057_50570202_89_dialog_content = "¡No hay de nuevo!",
  ui_story_5057_50570202_90_dialog_content = "¿Eh? ¿Se fueron así nomás?",
  ui_story_5057_50570202_91_dialog_content = "<color=#e8d9bb>Más tarde, Cena me pide salir y tomar su lección de nuevo... No puedo creer que sea una persona tan evasiva.</color>",
  ui_story_5057_50570301_1_dialog_content = "Hmm, siento algo muy familiar en la multitud por ahí.",
  ui_story_5057_50570301_2_dialog_content = "La sensación de bañarse en la luz solar brillante y estar rodeado de exuberantes plantas en el bosque...",
  ui_story_5057_50570301_3_dialog_content = "Hola, PlayerName, qué casualidad encontrarte tan pronto.",
  ui_story_5057_50570301_4_dialog_content = "Naroxel! ¡Sabía que eras tú!",
  ui_story_5057_50570301_5_dialog_content = "Pareces sorprendido.",
  ui_story_5057_50570301_6_dialog_content = "Oh, no, en absoluto.",
  ui_story_5057_50570301_7_dialog_content = "Cómo debería decirlo...",
  ui_story_5057_50570301_8_dialog_content = "Me sorprende un poco que pudiera percibirte sin usar mis habilidades psíquicas, Naroxel.",
  ui_story_5057_50570301_9_dialog_content = "El aire único que tienes... es muy distinto.",
  ui_story_5057_50570301_10_dialog_content = "¿Oh...?",
  ui_story_5057_50570301_11_dialog_content = "(¿Vaya, acabo de decir algo ofensivo?)",
  ui_story_5057_50570301_12_dialog_content = "¿Puedo tomar eso como que tienes una buena impresión de mí, PlayerName?",
  ui_story_5057_50570301_13_dialog_content = "¡Oh, sí, absolutamente!",
  ui_story_5057_50570301_14_dialog_content = "Eso podría ser porque nosotros, los Celestitas, estamos cerca de la naturaleza.",
  ui_story_5057_50570301_15_dialog_content = "Lo cual explica por qué siento afinidad contigo cuando te veo.",
  ui_story_5057_50570301_16_dialog_content = "Ya veo. Me alegra que pienses tan bien de mí.",
  ui_story_5057_50570301_17_dialog_content = "Por cierto, ¿estás libre ahora mismo, PlayerName?",
  ui_story_5057_50570301_18_dialog_content = "Si es así, me gustaría pedirle que me muestre el parque.",
  ui_story_5057_50570301_19_dialog_content = "Tengo varios días libres y los pasaré en este complejo turístico.",
  ui_story_5057_50570301_20_dialog_content = "Pero aún no estoy familiarizado con las atracciones más grandes y no sé cómo relajarme completamente.",
  ui_story_5057_50570301_21_dialog_content = "Imagino que sería mucho más feliz contigo en compañía.",
  ui_story_5057_50570301_22_option_content = "¡Por supuesto, no hay problema!",
  ui_story_5057_50570301_23_dialog_content = "¡Conozco todo el complejo turístico como la palma de mi mano!",
  ui_story_5057_50570301_24_dialog_content = "Déjame planificar un Tour Especial Guiado por Caelestite para ti.",
  ui_story_5057_50570301_25_option_content = "Bueno...",
  ui_story_5057_50570301_26_dialog_content = "¿Tienes otros negocios a los que atender?",
  ui_story_5057_50570301_27_dialog_content = "Entonces no debería retenerte...",
  ui_story_5057_50570301_28_dialog_content = "¡Para nada! Solo estaba planeando un recorrido especial guiado por Caelestite para ti.",
  ui_story_5057_50570301_29_dialog_content = "Entonces, cuento contigo, PlayerName.",
  ui_story_5057_50570301_30_dialog_content = "Uf... No puedo creer que estoy empapado de pies a cabeza.",
  ui_story_5057_50570301_31_dialog_content = "¿Qué opinas de este paseo rápido Bluefire Lava?",
  ui_story_5057_50570301_32_dialog_content = "Mientras te envía desde lo alto hacia abajo por la corriente, te bombardean con cálidos chorros de agua.",
  ui_story_5057_50570301_33_dialog_content = "Combina eso con un paisaje que imita un volcán y efectos de iluminación y sonido bien diseñados...",
  ui_story_5057_50570301_34_dialog_content = "¡Es seguro que recreará la emoción de escapar de un volcán a punto de entrar en erupción!",
  ui_story_5057_50570301_35_dialog_content = "¿Cómo te sientes, Naroxel? ¿La emoción hizo desaparecer todo el estrés de tus hombros?",
  ui_story_5057_50570301_36_dialog_content = "Fue muy emocionante, así es.",
  ui_story_5057_50570301_37_dialog_content = "Me recordó a una tarea de mensajero cuando me encontré con un volcán en erupción.",
  ui_story_5057_50570301_38_dialog_content = "Fue extremadamente peligroso. Tenía una mochila llena y corrí con todo lo que tenía.",
  ui_story_5057_50570301_39_dialog_content = "Estuve cerca de la perdición varias veces antes de finalmente huir de la zona y preservar el correo intacto.",
  ui_story_5057_50570301_40_dialog_content = "EveAunque entregué todo a tiempo...",
  ui_story_5057_50570301_41_dialog_content = "Mi ropa estaba chamuscada. Todavía recuerdo lo terrible que fue para mí.",
  ui_story_5057_50570301_42_dialog_content = "No muchas personas podrían lograr eso, Naroxel...",
  ui_story_5057_50570301_43_dialog_content = "Supongo que este paseo no es lo suficientemente importante para ti. ¡Vamos a golpear el próximo!",
  ui_story_5057_50570301_44_dialog_content = "Uf... ¿qué tal este?",
  ui_story_5057_50570301_45_dialog_content = "El Brain Blender cuenta con 22 caídas libres... Ese número supuestamente se basa en... *náuseas*",
  ui_story_5057_50570301_46_dialog_content = "¿Estás bien, PlayerName?",
  ui_story_5057_50570301_47_dialog_content = "Estoy bien, gracias...",
  ui_story_5057_50570301_48_dialog_content = "Estaba tan mareado en ese paseo, casi me desmayo, pero tú disfrutabas del paisaje como si no fuera nada...",
  ui_story_5057_50570301_49_dialog_content = "Para ser honesto, era mi primera vez disfrutando de la vista desde esa altura.",
  ui_story_5057_50570301_50_dialog_content = "Así que no pude evitar sumergirme.",
  ui_story_5057_50570301_51_dialog_content = "Hmm, parece que atracciones como esta son demasiado suaves para ti, Naroxel...",
  ui_story_5057_50570301_52_dialog_content = "¡Cielos, esta máquina está loca! ¡Mis dentaduras postizas de oro completamente nuevas casi salen volando de mi boca!",
  ui_story_5057_50570301_53_dialog_content = "¿Llamas a eso loco? Una vez escuché sobre un niño que lo lanzaron a la piscina y luego simplemente desapareció.",
  ui_story_5057_50570301_54_dialog_content = "Después de eso, todos los que montaron el Brain Blender y alcanzaron la cima sin cerrar los ojos escucharían sus sollozos por la noche.",
  ui_story_5057_50570301_55_dialog_content = "...",
  ui_story_5057_50570301_56_dialog_content = "¿Naroxel?",
  ui_story_5057_50570301_57_dialog_content = "N-Nada.",
  ui_story_5057_50570301_58_dialog_content = "¿Dónde escuchaste esto? ¿No es este un parque de diversiones nuevo? ¿Cómo podría haber tal accidente?",
  ui_story_5057_50570301_59_dialog_content = "Mira, lo dice justo ahí en ese cartel, \"Leyenda de la Licuadora de Cerebros.\"",
  ui_story_5057_50570301_60_dialog_content = "No puedo creer que compartas contenido promocional con otros como si fuera una historia real...",
  ui_story_5057_50570301_61_dialog_content = "...",
  ui_story_5057_50570301_62_dialog_content = "Jaja, supongo que es solo una historia que Cena inventó para promocionar la atracción.",
  ui_story_5057_50570301_63_dialog_content = "¿A dónde deberíamos ir después? ¡Hay muchas más atracciones emocionantes alrededor!",
  ui_story_5057_50570301_64_dialog_content = "Odio ser grosero, pero ¿hay un lugar cercano para descansar?",
  ui_story_5057_50570301_65_dialog_content = "Hay un pequeño terreno para acampar cerca de aquí con plantas frondosas.",
  ui_story_5057_50570301_66_dialog_content = "Me gustaría ir allí, por favor.",
  ui_story_5057_50570301_67_dialog_content = "Uf, un lugar tan verde es realmente relajante.",
  ui_story_5057_50570301_68_dialog_content = "¿Te importa si me acuesto un rato?",
  ui_story_5057_50570301_69_dialog_content = "¡Para nada!",
  ui_story_5057_50570301_70_dialog_content = "Todos los paseos que me llevaste fueron muy divertidos y emocionantes.",
  ui_story_5057_50570301_71_dialog_content = "Pero me siento realmente cómodo aquí, especialmente cuando estás conmigo.",
  ui_story_5057_50570301_72_dialog_content = "Lo que me gustaría decir es que espero no haber arruinado el tour especial que tenías planeado para mí.",
  ui_story_5057_50570301_73_dialog_content = "Para nada. Mientras tú estés feliz, yo estoy feliz.",
  ui_story_5057_50570301_74_dialog_content = "(Esa sensación de estar rodeado de plantas exuberantes cuando conocí a Naroxel se ha convertido en una realidad tangible...)",
  ui_story_5057_50570301_75_dialog_content = "Creo que estoy completamente sumergido en todo este verde...",
  ui_story_5057_50570301_76_dialog_content = "Zzzzz...",
  ui_story_5057_50570301_77_dialog_content = "¿Eh?",
  ui_story_5057_50570301_78_dialog_content = "(Naroxel se durmió.)",
  ui_story_5057_50570301_79_dialog_content = "(Su rostro es sereno y tranquilo, incluso tiene una sonrisa.)",
  ui_story_5057_50570301_80_dialog_content = "Mmm...",
  ui_story_5057_50570301_81_dialog_content = "(Debería dejarla sola por ahora...)",
  ui_story_5057_50570301_82_dialog_content = "<color=#e8d9bb>Más tarde, me preocupo de que Naroxel pueda tener frío, así que la cubro con mi ropa.</color>",
  ui_story_5057_50570302_1_dialog_content = "Lo siento, PlayerName, no quería quedarme dormido.",
  ui_story_5057_50570302_2_dialog_content = "No te preocupes. Te ves mucho mejor ahora.",
  ui_story_5057_50570302_3_dialog_content = "Sí, ha pasado mucho tiempo desde que pude relajarme en este ambiente.",
  ui_story_5057_50570302_4_dialog_content = "Me siento descansado tanto física como mentalmente.",
  ui_story_5057_50570302_5_dialog_content = "Eso es maravilloso.",
  ui_story_5057_50570302_6_dialog_content = "De hecho, tengo una solicitud...",
  ui_story_5057_50570302_7_dialog_content = "Avísame y haré lo mejor que pueda.",
  ui_story_5057_50570302_8_dialog_content = "¿Podemos saltarnos todas las atracciones emocionantes más tarde?",
  ui_story_5057_50570302_9_dialog_content = "¡Seguro!",
  ui_story_5057_50570302_10_dialog_content = "Para algo que es menos que un paseo emocionante, podemos probar la rueda de la fortuna.",
  ui_story_5057_50570302_11_dialog_content = "Tiene vista a todo el complejo, ¡y la vista desde la cima es grandiosa!",
  ui_story_5057_50570302_12_dialog_content = "O si lo que deseas es naturaleza, la plataforma de observación del cañón es una opción.",
  ui_story_5057_50570302_13_dialog_content = "Tiene un paisaje magnífico con muchos senderos para hacer senderismo.",
  ui_story_5057_50570302_14_dialog_content = "Oh, y está el bosque ribereño debajo del cañón. Te encantará, seguro.",
  ui_story_5057_50570302_15_dialog_content = "Está cerca de donde estamos ahora.",
  ui_story_5057_50570302_16_dialog_content = "Bosque fluvial... Eso sí suena relajante y reconfortante.",
  ui_story_5057_50570302_17_dialog_content = "Vamos allá.",
  ui_story_5057_50570302_18_dialog_content = "Qué encantador es esto...",
  ui_story_5057_50570302_19_dialog_content = "El arroyo claro y los frondosos bosques realmente pueden relajarte.",
  ui_story_5057_50570302_20_dialog_content = "El rico aroma de las plantas en el aire también es estimulante.",
  ui_story_5057_50570302_21_dialog_content = "Gracias, PlayerName, por mostrarme el hermoso paisaje.",
  ui_story_5057_50570302_22_dialog_content = "Me alegro de que te guste.",
  ui_story_5057_50570302_23_dialog_content = "Ven aquí, PlayerName.",
  ui_story_5057_50570302_24_dialog_content = "¿Qué tal?",
  ui_story_5057_50570302_25_dialog_content = "Aquí tienes pimienta, utilizable como condimento después de molerla.",
  ui_story_5057_50570302_26_dialog_content = "Es picante y un excelente complemento para platos en invierno.",
  ui_story_5057_50570302_27_dialog_content = "Esto es konjac, que supuestamente puede despertar tu mente. Se come en muchos lugares.",
  ui_story_5057_50570302_28_dialog_content = "Oh, y este árbol aquí, su fibra es flexible y duradera como para ser transformada en cuerdas de arco.",
  ui_story_5057_50570302_29_dialog_content = "No sabía que tenías un conocimiento tan profundo de las plantas, Naroxel.",
  ui_story_5057_50570302_30_dialog_content = "Bueno, los mensajeros a veces se encuentran con situaciones inesperadas en sus entregas.",
  ui_story_5057_50570302_31_dialog_content = "Entonces, es parte de nuestro trabajo aprender cosas que puedan ayudar a los demás.",
  ui_story_5057_50570302_32_dialog_content = "Mensajero suena como una elección de carrera muy impresionante...",
  ui_story_5057_50570302_33_dialog_content = "Jajaja... Dove sigue apareciendo en mi mente cuando pienso en mensajeros, probablemente porque ella dejó una gran impresión en mí.",
  ui_story_5057_50570302_34_dialog_content = "Dove le gusta holgazanear, pero te ayudó mucho, ¿no es cierto?",
  ui_story_5057_50570302_35_dialog_content = "¡Eso me recuerda! El Lumamber al principio era de Dove.",
  ui_story_5057_50570302_36_dialog_content = "Me alegra que los mensajeros hayan tenido un papel en tu viaje, PlayerName.",
  ui_story_5057_50570302_37_dialog_content = "Ah, mira allá.",
  ui_story_5057_50570302_38_dialog_content = "Las hojas tienen un patrón distintivo. Podría ser una especie única de esta área.",
  ui_story_5057_50570302_39_dialog_content = "¿Oh sí? Déjame ver.",
  ui_story_5057_50570302_40_dialog_content = "(Naroxel se siente diferente hoy de alguna manera, pero no puedo precisar exactamente en qué...)",
  ui_story_5057_50570302_41_dialog_content = "¿PlayerName?",
  ui_story_5057_50570302_42_dialog_content = "¡Lo siento! No quería mirar fijamente, solo me distraje por un momento.",
  ui_story_5057_50570302_43_dialog_content = "Es muy húmedo en el oasis, a veces causando falta de aliento y pérdida de concentración.",
  ui_story_5057_50570302_44_dialog_content = "Sigamos adelante.",
  ui_story_5057_50570302_45_dialog_content = "Seguro. Cuida tus pasos y no tropieces.",
  ui_story_5057_50570302_46_dialog_content = "Gracias por el recordatorio.",
  ui_story_5057_50570302_47_dialog_content = "(¿Vi cosas?)",
  ui_story_5057_50570302_48_dialog_content = "(Había tristeza en los ojos de Naroxel.)",
  ui_story_5057_50570302_49_dialog_content = "En realidad... Estoy muy feliz de pasar las vacaciones contigo, PlayerName.",
  ui_story_5057_50570302_50_dialog_content = "¿Qué?",
  ui_story_5057_50570302_51_dialog_content = "He tenido un cariño por los Celestitas y su forma de vida durante mucho tiempo.",
  ui_story_5057_50570302_52_dialog_content = "Porque tengo la típica sangre de demi-humano que es adversa al invierno, pero nací en Northland...",
  ui_story_5057_50570302_53_dialog_content = "Siempre he anhelado el agradable y perpetuamente templado Eraveil.",
  ui_story_5057_50570302_54_dialog_content = "Pero cuando hice una entrega allí, era irreconocible y carente de vida...",
  ui_story_5057_50570302_55_dialog_content = "Sí...",
  ui_story_5057_50570302_56_option_content = "Pero no me rendiré en mi casa.",
  ui_story_5057_50570302_57_dialog_content = "Eraveil significa todo para mí, y un día restauraré su gloria.",
  ui_story_5057_50570302_58_option_content = "Ahora está en ruinas.",
  ui_story_5057_50570302_59_dialog_content = "No estoy seguro de si tengo lo necesario para restaurarlo a su antigua gloria.",
  ui_story_5057_50570302_60_dialog_content = "Debes creer en ti mismo y en tus amigos.",
  ui_story_5057_50570302_61_dialog_content = "Tienes razón, Naroxel.",
  ui_story_5057_50570302_62_dialog_content = "Sabía que no estaba equivocado acerca de ti.",
  ui_story_5057_50570302_63_dialog_content = "Me alegra que no hayas huido de tus responsabilidades y hayas decidido reconstruir Eraveil.",
  ui_story_5057_50570302_64_dialog_content = "Sé que habrá muchos obstáculos en el camino, pero cuentas con mi ayuda.",
  ui_story_5057_50570302_65_dialog_content = "(Naroxel sostiene mis manos y siento que sus manos están frías.)",
  ui_story_5057_50570302_66_dialog_content = "Para el futuro de Celestitas y Eraveil.",
  ui_story_5057_50570302_67_dialog_content = "<color=#e8d9bb>Entonces montamos juntos en la rueda del cielo, Naroxel y yo, y disfrutamos de la vista nocturna del Denuo Valley Resort.</color>",
  ui_story_5057_50570401_1_dialog_content = "¿Dónde está el invitado? Falta solo un minuto para la hora acordada de encontrarnos...",
  ui_story_5057_50570401_2_dialog_content = "PlayerName...?",
  ui_story_5057_50570401_3_dialog_content = "Esa voz... Michenny?",
  ui_story_5057_50570401_4_dialog_content = "No serías el guía, ¿verdad, PlayerName?",
  ui_story_5057_50570401_5_dialog_content = "¡Soy! Tú eres el invitado, ya veo. No es de extrañar que estés justo a tiempo.",
  ui_story_5057_50570401_6_dialog_content = "Me halaga. Por cierto, ¿cómo es que trabajas como guía aquí?",
  ui_story_5057_50570401_7_dialog_content = "Bueno, eh... Es exactamente lo que parece, conseguí un trabajo...",
  ui_story_5057_50570401_8_dialog_content = "¿Un trabajo? Ya veo, es cuando cambias tu tiempo por dinero.",
  ui_story_5057_50570401_9_dialog_content = "¡Sí, esa es una descripción muy precisa!",
  ui_story_5057_50570401_10_dialog_content = "Está bien, supongo que te dejaré guiar el camino entonces, PlayerName.",
  ui_story_5057_50570401_11_dialog_content = "¡Sí, déjamelo a mí!",
  ui_story_5057_50570401_12_dialog_content = "Cielo Azul, Matriz Fantasía, Dragón de Noche Blanca, Disparos de Halo... Los hemos probado todos.",
  ui_story_5057_50570401_13_dialog_content = "Todo gracias a ti, PlayerName. Probablemente no podría probar tantos por mi cuenta.",
  ui_story_5057_50570401_14_dialog_content = "Aquí, toma una bebida. Acabo de enfriarla con Luminatics.",
  ui_story_5057_50570401_15_dialog_content = "¡Gracias!",
  ui_story_5057_50570401_16_dialog_content = "Trago, trago...",
  ui_story_5057_50570401_17_dialog_content = "¡Ah—! Es mucho mejor cuando está frío.",
  ui_story_5057_50570401_18_dialog_content = "Después de todo, el objetivo de venir al parque es divertirse.",
  ui_story_5057_50570401_19_dialog_content = "También me hace feliz verte dejar de lado el decoro por el puro disfrute.",
  ui_story_5057_50570401_20_dialog_content = "Estoy muy feliz, así es.",
  ui_story_5057_50570401_21_dialog_content = "Es muy divertido aquí, con muchas novedades.",
  ui_story_5057_50570401_22_dialog_content = "Oh, ¿qué es esto, PlayerName?",
  ui_story_5057_50570401_23_dialog_content = "¡Es una máquina de garra!",
  ui_story_5057_50570401_24_dialog_content = "¿Máquina de garra? No lo entiendo.",
  ui_story_5057_50570401_25_dialog_content = "Permíteme demostrar.",
  ui_story_5057_50570401_26_dialog_content = "Primero, inserta algunas monedas.",
  ui_story_5057_50570401_27_dialog_content = "Por favor dame un minuto... Son cinco monedas, ¿cierto?",
  ui_story_5057_50570401_28_dialog_content = "Sí. Quiere cinco Nightium porque este tiene mejores premios.",
  ui_story_5057_50570401_29_dialog_content = "Después de insertar las monedas, usa la palanca para posicionar la garra para recoger.",
  ui_story_5057_50570401_30_dialog_content = "¡Ahora elige algo que te guste!",
  ui_story_5057_50570401_31_dialog_content = "¡Está bien!",
  ui_story_5057_50570401_32_dialog_content = "Mueva la garra sobre el objeto con el palo.",
  ui_story_5057_50570401_33_dialog_content = "Mira desde todas las direcciones para calcular el ángulo y apunta la garra hacia él.",
  ui_story_5057_50570401_34_dialog_content = "¡Entonces presiona el botón!",
  ui_story_5057_50570401_35_dialog_content = "Vaya, está bajando.",
  ui_story_5057_50570401_36_dialog_content = "¡Lo tiene en su alcance!",
  ui_story_5057_50570401_37_dialog_content = "Sí. Ahora espera a que la garra traiga y suelte el premio en la caja.",
  ui_story_5057_50570401_38_dialog_content = "Estoy tan nervioso...",
  ui_story_5057_50570401_39_dialog_content = "¡Ah!",
  ui_story_5057_50570401_40_dialog_content = "La garra giró justo antes de soltarlo.",
  ui_story_5057_50570401_41_dialog_content = "Eso sucede a veces. Es más frecuente que falles en obtener un premio.",
  ui_story_5057_50570401_42_dialog_content = "Entonces, ¿qué pasa con las monedas cuando fallas?",
  ui_story_5057_50570401_43_dialog_content = "Eh, ¿los gastaste y ya se acabaron?",
  ui_story_5057_50570401_44_dialog_content = "¡¿Qué?!",
  ui_story_5057_50570401_45_dialog_content = "¿P-Por qué?",
  ui_story_5057_50570401_46_dialog_content = "No obtuve un premio. ¿Eso no significa que tengo derecho a un reembolso?",
  ui_story_5057_50570401_47_dialog_content = "Mmm, ¿cómo debería explicarlo...",
  ui_story_5057_50570401_48_dialog_content = "Obviamente invertiste esfuerzo y dinero, pero no obtuviste ningún retorno de ello.",
  ui_story_5057_50570401_49_dialog_content = "Basado en el tiempo invertido, vale al menos cincuenta Nightium.",
  ui_story_5057_50570401_50_dialog_content = "¿En serio? Creo que el tiempo vale solo diez Nightium, hasta donde yo sé.",
  ui_story_5057_50570401_51_dialog_content = "¡No es lo mismo hoy!",
  ui_story_5057_50570401_52_dialog_content = "Okay...",
  ui_story_5057_50570401_53_option_content = "¿Es porque hoy es un día festivo?",
  ui_story_5057_50570401_54_dialog_content = "¡Sí! Trabajar en un día festivo paga cinco veces la tarifa habitual.",
  ui_story_5057_50570401_55_option_content = "¿Es porque estoy trabajando como guía?",
  ui_story_5057_50570401_56_dialog_content = "Sí. Como mi guía, vales mucho más.",
  ui_story_5057_50570401_57_dialog_content = "Por no mencionar que creo que eres un excelente guía y mereces un bono.",
  ui_story_5057_50570401_58_dialog_content = "¿En serio? Estoy bien mientras tú te diviertas.",
  ui_story_5057_50570401_59_dialog_content = "Además, ¡el esfuerzo que pones debería exigir otras cincuenta Nightium!",
  ui_story_5057_50570401_60_dialog_content = "Juntos, eso hace ciento cinco Nightium, ¡o doscientos cinco para dos personas!",
  ui_story_5057_50570401_61_dialog_content = "E-Espera, Michenny!",
  ui_story_5057_50570401_62_dialog_content = "Esto es solo un juego. No puedes verlo de la misma manera.",
  ui_story_5057_50570401_63_dialog_content = "¿Eh?",
  ui_story_5057_50570401_64_dialog_content = "Permíteme decirlo de esta manera, estamos gastando dinero en la experiencia, no en el resultado.",
  ui_story_5057_50570401_65_dialog_content = "Lo importante aquí es disfrutar del proceso divertido con amigos.",
  ui_story_5057_50570401_66_dialog_content = "Ese es el caso para este juego también. Gasté las monedas porque quería que te divirtieras con la máquina.",
  ui_story_5057_50570401_67_dialog_content = "Fue interesante...",
  ui_story_5057_50570401_68_dialog_content = "La probabilidad de obtener un premio es baja, así que no esperaba nada.",
  ui_story_5057_50570401_69_dialog_content = "Ya veo...",
  ui_story_5057_50570401_70_dialog_content = "(Supongo que Michenny está empezando a entenderlo.)",
  ui_story_5057_50570401_71_dialog_content = "Gastar dinero para comprar experiencia...",
  ui_story_5057_50570401_72_dialog_content = "Cierto.",
  ui_story_5057_50570401_73_dialog_content = "Y la recompensa emocional de ello...",
  ui_story_5057_50570401_74_dialog_content = "¡Correcto!",
  ui_story_5057_50570401_75_dialog_content = "Con la oportunidad de ganar un premio...",
  ui_story_5057_50570401_76_dialog_content = "¡Sí, eso es exactamente!",
  ui_story_5057_50570401_77_dialog_content = "Eso es...",
  ui_story_5057_50570401_78_dialog_content = "¡Apuestas!",
  ui_story_5057_50570401_79_dialog_content = "¡Debo auditarte según las regulaciones de Lumopolis!",
  ui_story_5057_50570401_80_dialog_content = "¡V-Vaya, deja de forzar la ranura de la moneda!",
  ui_story_5057_50570401_81_dialog_content = "<color=#e8d9bb>Entonces, me esfuerzo al máximo para persuadir a Michenny y llevarla a ganar un montón de muñecos de la máquina de garra.</color>",
  ui_story_5057_50570402_1_dialog_content = "Ejem...",
  ui_story_5057_50570402_2_dialog_content = "Buenos dias, PlayerName.",
  ui_story_5057_50570402_3_dialog_content = "Buenos días, Michenny.",
  ui_story_5057_50570402_4_dialog_content = "Uh, lo siento por perder la calma la última vez.",
  ui_story_5057_50570402_5_dialog_content = "¿Eh? Oh, ¿te refieres a la máquina de garra?",
  ui_story_5057_50570402_6_dialog_content = "No creo que hayas perdido la calma.",
  ui_story_5057_50570402_7_option_content = "Pensé que era bastante lindo.",
  ui_story_5057_50570402_8_dialog_content = "Ya que siempre estás muy serio...",
  ui_story_5057_50570402_9_dialog_content = "Yo lo llamaría ver un lado más realista de ti, y es una gran diferencia.",
  ui_story_5057_50570402_10_dialog_content = "Ejem... ¿Tú lo crees?",
  ui_story_5057_50570402_11_option_content = "Todo el mundo se emociona de vez en cuando.",
  ui_story_5057_50570402_12_dialog_content = "Estoy seguro de que también te pasa a veces, Michenny.",
  ui_story_5057_50570402_13_dialog_content = "Lamento que hayas sido testigo.",
  ui_story_5057_50570402_14_dialog_content = "¿Serías mi guía de nuevo hoy, PlayerName?",
  ui_story_5057_50570402_15_dialog_content = "¡Estaré encantado de hacerlo!",
  ui_story_5057_50570402_16_dialog_content = "Uf, se gastó mucho en la tienda de souvenirs.",
  ui_story_5057_50570402_17_dialog_content = "Da miedo cuántas cosas Michenny compró...",
  ui_story_5057_50570402_18_dialog_content = "¿Crees que da miedo?",
  ui_story_5057_50570402_19_dialog_content = "¿No crees que este peluche de lagarto del desierto es lindo?",
  ui_story_5057_50570402_20_dialog_content = "Y esta caja tiene dulces de todos los sabores extraños del mundo... Tienes que comprar al por mayor para compartir con colegas y amigos en casa.",
  ui_story_5057_50570402_21_dialog_content = "Luego está la moneda conmemorativa. No es moneda de curso legal, pero la imagen en ella es muy agradable.",
  ui_story_5057_50570402_22_dialog_content = "Me recordará la diversión que tuve con PlayerName aquí cuando lo vea.",
  ui_story_5057_50570402_23_dialog_content = "Esta moneda tiene un valor mucho mayor al de una moneda regular.",
  ui_story_5057_50570402_24_dialog_content = "¿No es esa la lección que me enseñaste, PlayerName?",
  ui_story_5057_50570402_25_dialog_content = "Uh, sí, supongo.",
  ui_story_5057_50570402_26_dialog_content = "Después de todo, estás en unas vacaciones raras, así que deberías gastar dinero en lo que quieres y te gusta.",
  ui_story_5057_50570402_27_dialog_content = "Es difícil gastar dinero, de todos modos, cuando estás ocupado trabajando todo el tiempo.",
  ui_story_5057_50570402_28_dialog_content = "Vive la vida al máximo, lo que significa que cuando llega el momento adecuado, el dinero gastado tiene una importancia mucho mayor de lo habitual.",
  ui_story_5057_50570402_29_dialog_content = "Creo que eso es lo que me enseñaste la última vez.",
  ui_story_5057_50570402_30_dialog_content = "Vaya, aprendes rápido, Michenny.",
  ui_story_5057_50570402_31_dialog_content = "Entonces, ¿por qué te ves sorprendido?",
  ui_story_5057_50570402_32_dialog_content = "Porque no sonaba como lo que dirías normalmente, ¡supongo que estoy viendo otro lado de Michenny!",
  ui_story_5057_50570402_33_dialog_content = "Por supuesto, la multifacética de las personas es la razón por la que es difícil medirlas por dinero.",
  ui_story_5057_50570402_34_dialog_content = "Tener diversas emociones y diferentes apariencias también es valioso en cierto sentido.",
  ui_story_5057_50570402_35_dialog_content = "En cuanto a que veas otro lado de mí, tomaré eso como un cumplido.",
  ui_story_5057_50570402_36_dialog_content = "¡Por supuesto que es!",
  ui_story_5057_50570402_37_dialog_content = "Uf, estoy de mucho mejor ánimo después de ir de compras...",
  ui_story_5057_50570402_38_dialog_content = "Oye, ¿qué es ese edificio allá? No creo que hayamos estado allí todavía.",
  ui_story_5057_50570402_39_dialog_content = "Oh, esa es una atracción que aún no está abierta al público, pero creo que la están probando ahora.",
  ui_story_5057_50570402_40_dialog_content = "Hmm...",
  ui_story_5057_50570402_41_dialog_content = "Vamos a verlo. Una experiencia completa será cien Nightium más valiosa que un recuerdo de irse con arrepentimiento.",
  ui_story_5057_50570402_42_dialog_content = "¿Eh? Espera, Michenny!",
  ui_story_5057_50570402_43_dialog_content = "¡Deja de correr! Es peligroso visitar atracciones no inauguradas!",
  ui_story_5057_50570402_44_dialog_content = "Oye, ¿por qué no se puede abrir la puerta?",
  ui_story_5057_50570402_45_dialog_content = "¿No sería perfecto? Es difícil tener todo el lugar para ti solo.",
  ui_story_5057_50570402_46_dialog_content = "¡De ninguna manera! Tampoco puedo entender nada... ¿Cómo vamos a disfrutarlo?",
  ui_story_5057_50570402_47_dialog_content = "*sollozo*...",
  ui_story_5057_50570402_48_dialog_content = "Espera, oigo algo...",
  ui_story_5057_50570402_49_dialog_content = "El escalofriante chillido... ¿Es Eclipsite?",
  ui_story_5057_50570402_50_dialog_content = "No, ¡no siento Darkflow en ningún lugar aquí adentro!",
  ui_story_5057_50570402_51_dialog_content = "¿Puede ser esto... *trago*",
  ui_story_5057_50570402_52_dialog_content = "¿Qué te hizo tragar, PlayerName...",
  ui_story_5057_50570402_53_dialog_content = "Ahora recuerdo. Entre las atracciones inconclusas hay una casa embrujada llamada Fantasma Frenesí.",
  ui_story_5057_50570402_54_dialog_content = "Lleno de cosas aterradoras en su interior...",
  ui_story_5057_50570402_55_dialog_content = "¿Q-Qué? No puede ser... Es infantil...",
  ui_story_5057_50570402_56_dialog_content = "¡Ugh...!",
  ui_story_5057_50570402_57_dialog_content = "¡Eeek!",
  ui_story_5057_50570402_58_dialog_content = "S-¡Deja de empujarme, Michenny!",
  ui_story_5057_50570402_59_dialog_content = "Abre la puerta, ¡ábrela ahora!",
  ui_story_5057_50570402_60_dialog_content = "Devuélvelo... ¡Devuélveme mi Lumamber, ahora!",
  ui_story_5057_50570402_61_dialog_content = "!!!",
  ui_story_5057_50570402_62_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5057_50570402_63_dialog_content = "M-Michenny...?",
  ui_story_5057_50570402_64_dialog_content = "Entonces, eso no fue Lorelei?",
  ui_story_5057_50570402_65_dialog_content = "<color=#e8d9bb>Entonces, para tranquilizar a Michenny, la llevo a cenar y me esfuerzo mucho en explicar cómo funciona la casa embrujada.</color>",
  ui_story_5057_50570501_1_dialog_content = "Florine...",
  ui_story_5057_50570501_2_dialog_content = "Oh, ahí estás.",
  ui_story_5057_50570501_3_dialog_content = "Huff, huff... lamento haberte hecho esperar.",
  ui_story_5057_50570501_4_dialog_content = "Está bien. Yo tampoco llevo mucho tiempo aquí.",
  ui_story_5057_50570501_5_dialog_content = "Como caballero de la división, tengo la paciencia.",
  ui_story_5057_50570501_6_dialog_content = "Me alegra saber que llego aceptablemente tarde.",
  ui_story_5057_50570501_7_dialog_content = "Después de recibir tu mensaje, me cambié a un traje de baño y me apresuré a ir de inmediato.",
  ui_story_5057_50570501_8_dialog_content = "Hmm...",
  ui_story_5057_50570501_9_dialog_content = "(Algo sobre Florine hoy día...)",
  ui_story_5057_50570501_10_dialog_content = "(¿Es porque está en traje de baño?)",
  ui_story_5057_50570501_11_dialog_content = "¿Has visto suficiente, PlayerName?",
  ui_story_5057_50570501_12_dialog_content = "Vaya, pillado.",
  ui_story_5057_50570501_13_dialog_content = "Siento como si estuviera bajo la luz de una bombilla de un millón de vatios.",
  ui_story_5057_50570501_14_dialog_content = "¡Lo siento, no quería mirarte así!",
  ui_story_5057_50570501_15_dialog_content = "Uh, bueno, creo que te ves particularmente adorable hoy, no puedo evitar querer encontrar qué te hace diferente.",
  ui_story_5057_50570501_16_dialog_content = "Esa es una excusa bastante débil, pero acepto.",
  ui_story_5057_50570501_17_dialog_content = "Por cierto, también seguías mirando la última vez que llevaba un traje de baño.",
  ui_story_5057_50570501_18_dialog_content = "EveAunque no es suficiente para hacerme enojar... o feliz.",
  ui_story_5057_50570501_19_dialog_content = "Tienes que concentrarte en la misión que estamos a punto de llevar a cabo.",
  ui_story_5057_50570501_20_dialog_content = "¡Sí! Me alegra que no estés enojado, Florine.",
  ui_story_5057_50570501_21_dialog_content = "Oh, ¿mencionaste una misión para hoy?",
  ui_story_5057_50570501_22_dialog_content = "Discutiremos esto mientras avanzamos.",
  ui_story_5057_50570501_23_dialog_content = "¡Claro!",
  ui_story_5057_50570501_24_dialog_content = "Estoy emocionado por la misión. Dime qué es.",
  ui_story_5057_50570501_25_dialog_content = "¡Y es un honor trabajar junto a Florine!",
  ui_story_5057_50570501_26_dialog_content = "Eh, ¿cómo es que estás tan emocionado?",
  ui_story_5057_50570501_27_dialog_content = "Podría llamarlo una misión, pero en realidad no es nada especial.",
  ui_story_5057_50570501_28_dialog_content = "Es muy fácil, de hecho, y es pasar el día libre relajándose en el complejo turístico.",
  ui_story_5057_50570501_29_dialog_content = "¿Qué? ¿Eso también cuenta como una misión?",
  ui_story_5057_50570501_30_dialog_content = "Por supuesto, y necesito escribir un informe sobre ello esta noche.",
  ui_story_5057_50570501_31_dialog_content = "No debo entregarlo, pero es necesario resumir el día libre.",
  ui_story_5057_50570501_32_dialog_content = "Está bien. ¿Deberíamos golpear la arena o ir a nadar? May¿será un paseo o pescar?",
  ui_story_5057_50570501_33_dialog_content = "¡Si hay conchas, podemos ver quién encuentra la más grande!",
  ui_story_5057_50570501_34_dialog_content = "Uh, no tengo planes específicos, así que veremos cuando lleguemos allí.",
  ui_story_5057_50570501_35_dialog_content = "Sin embargo, parece que estás muy entusiasmado.",
  ui_story_5057_50570501_36_dialog_content = "Eso se debe a que cosas interesantes suelen ocurrir cuando un caballero de la División de Investigación de Herejes está de vacaciones conmigo.",
  ui_story_5057_50570501_37_dialog_content = "De acuerdo, nada interesante sucederá en estas vacaciones.",
  ui_story_5057_50570501_38_dialog_content = "¡Tengo una fuerte sensación!",
  ui_story_5057_50570501_39_dialog_content = "¿Sensación? ¿Como si algo interesante fuera a suceder?",
  ui_story_5057_50570501_40_dialog_content = "¡Sí!",
  ui_story_5057_50570501_41_dialog_content = "¡Es interesante simplemente estar con Florine!",
  ui_story_5057_50570501_42_dialog_content = "Ahora, eso es ir demasiado lejos...",
  ui_story_5057_50570501_43_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5057_50570501_44_dialog_content = "Vaya, lo siento.",
  ui_story_5057_50570501_45_dialog_content = "Estoy bien. No estás herido, ¿verdad?",
  ui_story_5057_50570501_46_dialog_content = "Estoy bien, ¡gracias! Eres un chico tierno y guapo.",
  ui_story_5057_50570501_47_dialog_content = "...",
  ui_story_5057_50570501_48_dialog_content = "Eso fue descuidado, casi me tira al suelo...",
  ui_story_5057_50570501_49_dialog_content = "...",
  ui_story_5057_50570501_50_dialog_content = "¿Oh?",
  ui_story_5057_50570501_51_dialog_content = "(F-Florine tiene esa mirada aterradora en sus ojos.)",
  ui_story_5057_50570501_52_dialog_content = "Tu traje de baño está suelto, PlayerName.",
  ui_story_5057_50570501_53_dialog_content = "No te muevas y déjame ayudar.",
  ui_story_5057_50570501_54_dialog_content = "¿Qué? ¡Oye?!",
  ui_story_5057_50570501_55_dialog_content = "No tan difícil, Florine!",
  ui_story_5057_50570501_56_dialog_content = "¡Me estás asfixiando!",
  ui_story_5057_50570501_57_dialog_content = "Toma una bebida, por favor.",
  ui_story_5057_50570501_58_dialog_content = "Trago, trago...",
  ui_story_5057_50570501_59_dialog_content = "Eh, sobre lo que acaba de pasar, me disculpo. Admito que perdí el enfoque en la misión.",
  ui_story_5057_50570501_60_dialog_content = "Bien, estás perdonado.",
  ui_story_5057_50570501_61_dialog_content = "Aunque no tienes que disculparte por eso. Eres libre de hacer lo que quieras... siempre y cuando no afecte el progreso de la tarea.",
  ui_story_5057_50570501_62_dialog_content = "Oh... Lo siento. Entonces, ¿qué te hizo decidir pescar?",
  ui_story_5057_50570501_63_dialog_content = "Porque es muy tranquilo y la vista es agradable.",
  ui_story_5057_50570501_64_dialog_content = "Tampoco es tan intenso como los paseos. ¿No crees que también es bueno relajarse y charlar libremente?",
  ui_story_5057_50570501_65_dialog_content = "Tú pareces cansado de todos los recados también... Esto debería darte más tiempo para relajarte.",
  ui_story_5057_50570501_66_dialog_content = "Cierto, últimamente he estado perdiendo la cabeza... Eres muy considerado, Florine.",
  ui_story_5057_50570501_67_dialog_content = "...",
  ui_story_5057_50570501_68_dialog_content = "Sin embargo, aún no he atrapado ni un pez.",
  ui_story_5057_50570501_69_dialog_content = "Me pregunto si los asusté.",
  ui_story_5057_50570501_70_dialog_content = "¿Te gustaría intentarlo, el tierno y apuesto Sr. Celestita?",
  ui_story_5057_50570501_71_dialog_content = "¿Yo? Sinceramente, soy bastante bueno en lo que respecta a pescar.",
  ui_story_5057_50570501_72_dialog_content = "¡Así que déjame intentarlo!",
  ui_story_5057_50570501_73_dialog_content = "Está bien, relájate y respira...",
  ui_story_5057_50570501_74_dialog_content = "(Florine ha estado fijándose en mí todo este tiempo.)",
  ui_story_5057_50570501_75_dialog_content = "Eh, ¿no deberías estar mirando el agua, Florine?",
  ui_story_5057_50570501_76_dialog_content = "Shhh, quiero estudiar tu postura de pescar.",
  ui_story_5057_50570501_77_dialog_content = "¿En serio? Está bien.",
  ui_story_5057_50570501_78_dialog_content = "¡...!",
  ui_story_5057_50570501_79_dialog_content = "¡Tengo una mordida! ¡Y una fuerte también!",
  ui_story_5057_50570501_80_dialog_content = "No puedo enrollarlo. ¡Me está arrastrando hacia abajo!",
  ui_story_5057_50570501_81_dialog_content = "Déjalo ir, PlayerName!",
  ui_story_5057_50570501_82_dialog_content = "<color=#e8d9bb>¡Chapoteo!</color>",
  ui_story_5057_50570501_83_dialog_content = "(Oh, ¿qué pasó...? Creo que me arrastró al agua un pez grande...)",
  ui_story_5057_50570501_84_dialog_content = "(¿Qué es esta cosa suave debajo de mi cabeza...?)",
  ui_story_5057_50570501_85_dialog_content = "Mmm... espera, ¿es... Florine?",
  ui_story_5057_50570501_86_dialog_content = "Por supuesto que soy yo, PlayerName.",
  ui_story_5057_50570501_87_dialog_content = "¿Te importaría dejar de hacer tonterías? Debería haber usado un cactus como tu almohada en lugar de eso...",
  ui_story_5057_50570501_88_dialog_content = "¡Lo siento! ¡Me levantaré ahora mismo!",
  ui_story_5057_50570501_89_dialog_content = "<color=#e8d9bb>Entonces, en un ambiente bastante sutil, ceno con Florine. ¿Está enojada o qué...?</color>",
  ui_story_5057_50570502_1_dialog_content = "Gracias por lo que hiciste, Florine.",
  ui_story_5057_50570502_2_dialog_content = "¿Eh?",
  ui_story_5057_50570502_3_dialog_content = "Acabas de salvar mi vida.",
  ui_story_5057_50570502_4_dialog_content = "Iba a conseguir el pescado, asarlo a la parrilla o convertirlo en una olla caliente de Longzhou que aprendí la última vez para tratarte.",
  ui_story_5057_50570502_5_dialog_content = "No esperaba que fuera tan fuerte...",
  ui_story_5057_50570502_6_dialog_content = "De nada.",
  ui_story_5057_50570502_7_dialog_content = "Pero olvida esa idea. Ese pez era lo suficientemente grande como para tragarnos a ambos.",
  ui_story_5057_50570502_8_dialog_content = "¿Eh?",
  ui_story_5057_50570502_9_dialog_content = "(¿Por qué hay un pez tan peligroso aquí?)",
  ui_story_5057_50570502_10_dialog_content = "Afortunadamente, tomé primeros auxilios como electiva en mi segundo semestre en la Dawn Academia.",
  ui_story_5057_50570502_11_dialog_content = "Ejem, a pesar de que casi nadie eligió el curso y se pasó por alto por completo.",
  ui_story_5057_50570502_X11_dialog_content = "Creo que cualquier conocimiento que salve vidas es valioso.",
  ui_story_5057_50570502_12_dialog_content = "Rezaba para no tener que usar nunca ese conocimiento, solo para que PlayerName fuera la primera víctima ahogada que salvé.",
  ui_story_5057_50570502_13_dialog_content = "Salvando a víctimas ahogadas... Recuerdo que Soroz me enseñó eso.",
  ui_story_5057_50570502_14_dialog_content = "PlayerName, ¿todavía recuerdas cómo rescatar a alguien que se está ahogando?",
  ui_story_5057_50570502_15_dialog_content = "Primero, necesitas sacar a la persona que se está ahogando del agua.",
  ui_story_5057_50570502_16_dialog_content = "Luego, verifica si aún respiran y tienen pulso.",
  ui_story_5057_50570502_17_dialog_content = "Si no, realice de inmediato medidas como compresiones en el pecho y respiración de rescate hasta que recuperen la conciencia o llegue ayuda profesional.",
  ui_story_5057_50570502_18_dialog_content = "Además, mantenga la cabeza más baja que el cuerpo para evitar que el vómito entre en las vías respiratorias.",
  ui_story_5057_50570502_19_dialog_content = "De nuevo, Soroz? No importa cuántas veces me enseñes, no tendré la oportunidad de usarlo...",
  ui_story_5057_50570502_20_dialog_content = "Mantén el ánimo arriba, PlayerName. Realmente espero que nunca tengas que usar estas cosas.",
  ui_story_5057_50570502_21_dialog_content = "Pero si ocurre un incidente inesperado, espero que puedas salvar a alguien querido con este conocimiento.",
  ui_story_5057_50570502_22_dialog_content = "Mmm, déjame pensar...",
  ui_story_5057_50570502_23_dialog_content = "Estaba acostado en tus piernas, ¿cierto?",
  ui_story_5057_50570502_24_dialog_content = "Sí, porque estabas respirando de nuevo.",
  ui_story_5057_50570502_25_dialog_content = "¿Respirando de nuevo? Eso significa que dejé de respirar...",
  ui_story_5057_50570502_26_option_content = "¡Así que debes haber...!",
  ui_story_5057_50570502_27_dialog_content = "¡Es solo un procedimiento médico normal, no hay necesidad de gritar!",
  ui_story_5057_50570502_28_dialog_content = "Solo hice eso porque accidentalmente caíste al agua...",
  ui_story_5057_50570502_29_dialog_content = "A-Y te despertaste justo después de que te hiciera las compresiones torácicas.",
  ui_story_5057_50570502_30_dialog_content = "Ah, claro...",
  ui_story_5057_50570502_31_option_content = "¡Así que prácticamente volví a respirar por mí mismo!",
  ui_story_5057_50570502_32_dialog_content = "Sí. Quién sabe, tal vez en realidad eres un pez.",
  ui_story_5057_50570502_33_dialog_content = "Lo siento, en ese momento solo podía pensar en qué plato preparar...",
  ui_story_5057_50570502_34_dialog_content = "Sin mencionar que me siento especialmente seguro cuando estoy contigo, Florine.",
  ui_story_5057_50570502_35_dialog_content = "No importa. Es bueno que estés bien. Es lo suficientemente difícil cuidarte todo el tiempo.",
  ui_story_5057_50570502_36_dialog_content = "No, ¡no puedo simplemente olvidarlo!",
  ui_story_5057_50570502_37_dialog_content = "¡Debo reembolsarte por la deuda!",
  ui_story_5057_50570502_38_dialog_content = "¿Q-Qué estás haciendo...?",
  ui_story_5057_50570502_39_dialog_content = "Sé que estás agradecido, PlayerName, pero esto es demasiado.",
  ui_story_5057_50570502_40_dialog_content = "¡Esto te va a costar hasta el último centavo de tu salario!",
  ui_story_5057_50570502_41_dialog_content = "No, ¡no es demasiado para mi salvador! ¡Siempre puedo recuperar mis ganancias!",
  ui_story_5057_50570502_42_dialog_content = "Déjame ver, entonces aquí compramos el Malvavisco de Polvo de Estrellas, helado sabor lagarto y jugo de menta-cactus.",
  ui_story_5057_50570502_43_dialog_content = "Además la bebida de cascada del cañón, y la Salchicha Galáctica.",
  ui_story_5057_50570502_44_dialog_content = "Correcto, y ambos de mis brazos están llenos.",
  ui_story_5057_50570502_45_dialog_content = "Esto debería ser suficiente, ¿cierto?",
  ui_story_5057_50570502_46_dialog_content = "Uh, no creo que sea suficiente todavía.",
  ui_story_5057_50570502_47_dialog_content = "¡Mira esto, el único espino confitado de Longzhou en todo el desierto de Rediesel!",
  ui_story_5057_50570502_48_dialog_content = "Acabo de cubrirlos con jarabe fresco. ¡Prueba un poco y nunca te arrepentirás!",
  ui_story_5057_50570502_49_dialog_content = "¡Dame uno, por favor!",
  ui_story_5057_50570502_50_dialog_content = "Esta es la primera vez que veo este refrigerio de Longzhou. Darle una oportunidad, Florine!",
  ui_story_5057_50570502_51_dialog_content = "Me gustaría mucho, pero tengo la mitad de la comida de esta calle en mis brazos ahora mismo...",
  ui_story_5057_50570502_52_dialog_content = "Verdadero... Oye, ¿qué tal si te alimento?",
  ui_story_5057_50570502_53_dialog_content = "¿Qué? N-No, eso no está bien. Me niego.",
  ui_story_5057_50570502_54_dialog_content = "Vamos, toma un mordisco... ¡Ups, se está cayendo el azúcar glas!",
  ui_story_5057_50570502_55_dialog_content = "Oh, ¿en serio?",
  ui_story_5057_50570502_56_dialog_content = "<color=#e8d9bb>Florine mastica rápidamente esa fruta más baja, su vibrante superficie roja goteando con jarabe dulce.</color>",
  ui_story_5057_50570502_57_dialog_content = "Supongo que está bien.",
  ui_story_5057_50570502_58_dialog_content = "¡Oh! Qué envidia me dan ustedes, jóvenes, divirtiéndose en la carretera así.",
  ui_story_5057_50570502_59_dialog_content = "¡...!",
  ui_story_5057_50570502_60_dialog_content = "¿Hicimos algo mal?",
  ui_story_5057_50570502_61_dialog_content = "¿Por qué está tan roja tu cara, Florine? ¿La comida que sirve hace que la cara de la gente se ponga roja, señor?",
  ui_story_5057_50570502_62_dialog_content = "¡PlayerName!",
  ui_story_5057_50570502_63_dialog_content = "¡Estoy aquí! ¿Qué ocurre?",
  ui_story_5057_50570502_64_dialog_content = "Ábrelo. La papa al horno también es muy buena.",
  ui_story_5057_50570502_65_dialog_content = "Simplemente entrégamelo... ¡Oh!",
  ui_story_5057_50570502_66_dialog_content = "<color=#e8d9bb>Florine, todo sonrojado, mete una papa asada directamente en mi boca.</color>",
  ui_story_5057_50570502_67_dialog_content = "¡Ustedes tienen un vínculo tan estupendo! Aquí, déjenme conseguirles otro tazón ¡gratis!",
  ui_story_5057_50570502_68_dialog_content = "<color=#e8d9bb>Más tarde, Florine insiste en dividir los gastos conmigo. Eso es tan... Florine.</color>",
  ui_story_5057_50570601_1_dialog_content = "Estoy nervioso.",
  ui_story_5057_50570601_2_dialog_content = "Claro, soy amigo de Su Majestad Bethlehem...",
  ui_story_5057_50570601_3_dialog_content = "Pero aún me estreso cuando me encuentro con ella a solas, por alguna razón...",
  ui_story_5057_50570601_4_dialog_content = "Por no mencionar que estoy representando al complejo en nombre de Lorelei...",
  ui_story_5057_50570601_5_dialog_content = "Soy presentable, ¿verdad...? Oh, he estado usando esto todo el tiempo.",
  ui_story_5057_50570601_6_dialog_content = "Entonces probablemente no traeré vergüenza a los Celestitas... Espero que no...",
  ui_story_5057_50570601_7_dialog_content = "Y, con suerte, tampoco será una vergüenza para el complejo turístico.",
  ui_story_5057_50570601_8_dialog_content = "PlayerName.",
  ui_story_5057_50570601_9_dialog_content = "Lorelei no me descontaría el salario, ¿verdad?",
  ui_story_5057_50570601_10_dialog_content = "¿PlayerName?",
  ui_story_5057_50570601_11_dialog_content = "¡S-Sí!",
  ui_story_5057_50570601_12_dialog_content = "¡Su Majestad!",
  ui_story_5057_50570601_13_dialog_content = "No estoy interrumpiendo nada, ¿verdad?",
  ui_story_5057_50570601_14_dialog_content = "¿Pareces preocupado?",
  ui_story_5057_50570601_15_dialog_content = "¡No, no, para nada! Ser su anfitrión siempre es un placer, Su Majestad.",
  ui_story_5057_50570601_16_dialog_content = "Lorelei se ha estado culpando a sí misma por no entretenerte antes, ya que estaba ocupada con los Eclipsites.",
  ui_story_5057_50570601_17_dialog_content = "Y espero que disfrutes de estas raras vacaciones en el complejo turístico.",
  ui_story_5057_50570601_18_dialog_content = "Ya que imagino que los asuntos del tribunal probablemente te agotaron.",
  ui_story_5057_50570601_19_dialog_content = "Ya veo. Lo aprecio.",
  ui_story_5057_50570601_20_dialog_content = "Jajaja, no importa cuántas veces monte al Dragón de la Noche Blanca, sigue siendo emocionante.",
  ui_story_5057_50570601_21_dialog_content = "Mis piernas aún están temblando ahora...",
  ui_story_5057_50570601_22_dialog_content = "Pero parece tranquilo y recogido, Su Majestad.",
  ui_story_5057_50570601_23_dialog_content = "De hecho, ya que estoy acostumbrado a montar un dragón volador.",
  ui_story_5057_50570601_24_dialog_content = "Realmente experimentó todo, Su Majestad.",
  ui_story_5057_50570601_25_dialog_content = "Té y bocadillo para ti.",
  ui_story_5057_50570601_26_dialog_content = "Gracias, PlayerName.",
  ui_story_5057_50570601_27_dialog_content = "¿Dónde está tu porción?",
  ui_story_5057_50570601_28_dialog_content = "Oh, Lorelei le dijo al chef que preparara esto especialmente para ti.",
  ui_story_5057_50570601_29_dialog_content = "Escuché que utilizaba muchos ingredientes preciosos y costosos.",
  ui_story_5057_50570601_30_dialog_content = "¿En serio?",
  ui_story_5057_50570601_31_dialog_content = "(Hmm, no creo que Queen Bethlehem esté de muy buen ánimo.)",
  ui_story_5057_50570601_32_dialog_content = "PlayerName.",
  ui_story_5057_50570601_33_dialog_content = "¡Muy bien, Su Majestad!",
  ui_story_5057_50570601_34_dialog_content = "Tengo una pregunta.",
  ui_story_5057_50570601_35_dialog_content = "Por favor, pregunta.",
  ui_story_5057_50570601_36_dialog_content = "¿En qué rol me acompañas, PlayerName?",
  ui_story_5057_50570601_37_option_content = "Eh, ¿anfitrión del complejo turístico?",
  ui_story_5057_50570601_38_dialog_content = "Me pagan un salario por Lorelei después de todo...",
  ui_story_5057_50570601_39_option_content = "Eh, ¿un amigo cercano de Su Majestad?",
  ui_story_5057_50570601_40_dialog_content = "Bueno, eso probablemente sea exagerado.",
  ui_story_5057_50570601_41_dialog_content = "Pero creo que puedo manejar el trabajo, ¿cierto?",
  ui_story_5057_50570601_42_dialog_content = "No creo que eso me tranquilice completamente.",
  ui_story_5057_50570601_43_dialog_content = "Gracias al destino, nos conocemos desde hace bastante tiempo, pero aún pareces preocupado por mi posición.",
  ui_story_5057_50570601_44_dialog_content = "Pero tú eres el Queen del Norte... Preferiría no ofenderte siendo demasiado informal.",
  ui_story_5057_50570601_45_dialog_content = "No, no me estás ofendiendo.",
  ui_story_5057_50570601_46_dialog_content = "Siento que la vibra en este momento está creando una brecha entre nosotros.",
  ui_story_5057_50570601_47_dialog_content = "Tu actitud me hace sentir que estoy en una función oficial.",
  ui_story_5057_50570601_48_dialog_content = "Lo siento...",
  ui_story_5057_50570601_49_dialog_content = "Por favor, no bajes la cabeza, Celestita. ¿Todavía recuerdas que eres el elegido?",
  ui_story_5057_50570601_50_dialog_content = "¡Por supuesto que sí!",
  ui_story_5057_50570601_51_dialog_content = "Si realmente quieres ayudarme a aliviar el estrés...",
  ui_story_5057_50570601_52_dialog_content = "Entonces ayúdame a olvidar mi estatus de reina y saltar esos protocolos sofocantes.",
  ui_story_5057_50570601_53_dialog_content = "Relájate, especialmente cuando solo somos los dos.",
  ui_story_5057_50570601_54_dialog_content = "Por ahora, quiero pasar el rato y relajarme contigo como amigo, PlayerName.",
  ui_story_5057_50570601_55_dialog_content = "Pero estoy un poco desanimado porque siempre me pones en un pedestal alto.",
  ui_story_5057_50570601_56_dialog_content = "Por favor, trátame solo como un amigo por el momento. Siéntete libre de bromear y hacer chistes.",
  ui_story_5057_50570601_57_dialog_content = "No me importarán los errores que puedas cometer, y esto hará que nuestras vacaciones sean mejores y nos acerquen más.",
  ui_story_5057_50570601_58_dialog_content = "Por favor, disculpa mi ignorancia. Entiendo lo que dices ahora.",
  ui_story_5057_50570601_59_dialog_content = "Comenzaré a tratarte como un amigo de ahora en adelante, Su Majestad.",
  ui_story_5057_50570601_60_dialog_content = "Está bien.",
  ui_story_5057_50570601_61_dialog_content = "(Ella está sonriendo al fin...)",
  ui_story_5057_50570601_62_dialog_content = "Supongo que puedo relajarme ahora.",
  ui_story_5057_50570601_63_dialog_content = "Oh, una cosa más.",
  ui_story_5057_50570601_64_dialog_content = "¿Qué sucede, Su Majestad?",
  ui_story_5057_50570601_65_dialog_content = "De ahora en adelante, por favor dejen de dirigirse a mí como Su Majestad o Queen.",
  ui_story_5057_50570601_66_dialog_content = "No deseo que otros invitados conozcan mi identidad.",
  ui_story_5057_50570601_67_dialog_content = "Bueno, ¿cómo lo evito...?",
  ui_story_5057_50570601_68_dialog_content = "Belén.",
  ui_story_5057_50570601_69_dialog_content = "Llámame Belén mientras esté aquí.",
  ui_story_5057_50570601_70_dialog_content = "¿Qué?",
  ui_story_5057_50570601_71_dialog_content = "<color=#e8d9bb>EveAunque Queen Bethlehem mantiene su expresión tranquila y compuesta, puedo notar que su ánimo ha mejorado bastante.</color>",
  ui_story_5057_50570602_1_dialog_content = "El cielo azul es realmente demasiado para mí...",
  ui_story_5057_50570602_2_dialog_content = "Siento que una parte de mí se arranca de mi cuerpo cada vez que me empujan y reboto hacia arriba y hacia abajo.",
  ui_story_5057_50570602_3_dialog_content = "Pero Queen Bethlehem parece estar pasándolo muy bien.",
  ui_story_5057_50570602_4_dialog_content = "Me preguntaba si podría ser peligroso para ella.",
  ui_story_5057_50570602_5_dialog_content = "Supongo que me preocupé por nada.",
  ui_story_5057_50570602_6_dialog_content = "Uf...",
  ui_story_5057_50570602_7_dialog_content = "Belen... Belén, tu cabello está desordenado.",
  ui_story_5057_50570602_8_option_content = "Ayuda a Bethlehem ordenar",
  ui_story_5057_50570602_9_dialog_content = "Por favor, permíteme echarte una mano.",
  ui_story_5057_50570602_10_dialog_content = "Seguro, gracias.",
  ui_story_5057_50570602_11_option_content = "Espera a que Bethlehem se arregle",
  ui_story_5057_50570602_12_dialog_content = "Está bien, puedo encargarme de ello yo mismo.",
  ui_story_5057_50570602_13_dialog_content = "Lo siento, casi te llamo por el nombre equivocado de nuevo.",
  ui_story_5057_50570602_14_dialog_content = "No estés nervioso, sé que tomará un tiempo acostumbrarse. Solo relájate.",
  ui_story_5057_50570602_15_dialog_content = "¡Servirá! Pareces estar de mucho mejor ánimo. ¿Disfrutaste de Cielo Azul?",
  ui_story_5057_50570602_16_dialog_content = "(Solo me recuerda a Queen Bethlehem disparando más de una docena de armas jugando ese juego de Ruleta de la Suerte.)",
  ui_story_5057_50570602_17_dialog_content = "(La probabilidad de obtener un arma descargada en ese juego es de una en seis... Ella tiene una suerte increíble.)",
  ui_story_5057_50570602_18_dialog_content = "Este es más divertido para mí... Simplemente no tengo la oportunidad de relajarme como la gente normal, normalmente.",
  ui_story_5057_50570602_19_dialog_content = "Puedo ver eso, ya que tienes muchas cosas en tu plato como la reina.",
  ui_story_5057_50570602_20_dialog_content = "Gracias, pero no olvides que ahora soy Belén.",
  ui_story_5057_50570602_21_dialog_content = "¡Lo siento! Como disculpa, ¡disfruta de un vaso de jugo de cactus estrella por mi cuenta! Está muy delicioso.",
  ui_story_5057_50570602_22_dialog_content = "Entonces podemos ir a relajarnos en la rueda de la fortuna y pasar por alto el complejo turístico.",
  ui_story_5057_50570602_23_dialog_content = "Vuelvo enseguida.",
  ui_story_5057_50570602_24_dialog_content = "No puedo creer lo lleno que estaba el vendedor. Fue mucho tiempo de espera.",
  ui_story_5057_50570602_25_dialog_content = "Tengo que regresar. Queen Bethlehem debe estar preguntándose dónde estoy.",
  ui_story_5057_50570602_26_dialog_content = "¿Entonces qué dices, señorita?",
  ui_story_5057_50570602_27_dialog_content = "Siéntete libre de decir lo que piensas.",
  ui_story_5057_50570602_28_dialog_content = "...",
  ui_story_5057_50570602_29_dialog_content = "¿Quiénes son estos personas?",
  ui_story_5057_50570602_30_dialog_content = "Hola, amigo. ¿Tú y esta mujer joven son amigos?",
  ui_story_5057_50570602_31_dialog_content = "¿Quién eres?",
  ui_story_5057_50570602_32_dialog_content = "Perdón por la grosería. En realidad, soy un cazatalentos de Umbraton Beatitude Entertainment.",
  ui_story_5057_50570602_33_dialog_content = "Y debo decir que esta mujer joven aquí tiene una apariencia absolutamente impresionante. Es como una estrella nacida.",
  ui_story_5057_50570602_34_dialog_content = "Nuestra empresa es altamente influyente y si estás interesado en unirte a nosotros, ¡puedo presentarte algunas condiciones excepcionalmente atractivas!",
  ui_story_5057_50570602_35_dialog_content = "Estamos aquí de vacaciones y no tenemos planes de convertirnos en un ídolo o algo así.",
  ui_story_5057_50570602_36_dialog_content = "¡Sería una lástima desperdiciar un talento y potencial tan increíbles!",
  ui_story_5057_50570602_37_dialog_content = "Oye, amigo. ¿Es usted el agente de esta joven?",
  ui_story_5057_50570602_38_dialog_content = "Podemos tener una discusión de tres vías, y puedo prometerte una comisión sustancial.",
  ui_story_5057_50570602_39_dialog_content = "Perdóname, pero no queremos ser molestados.",
  ui_story_5057_50570602_40_dialog_content = "Qué pena. Bueno, tendré que buscar a alguien más.",
  ui_story_5057_50570602_41_dialog_content = "Señorita, ¿puedo dejarle mi información de contacto? ¡Tengo algunas oportunidades fantásticas para ti!",
  ui_story_5057_50570602_42_dialog_content = "Por favor, sal ahora o llamaré a seguridad.",
  ui_story_5057_50570602_43_dialog_content = "Mocoso, ¿qué acabas de decir...?",
  ui_story_5057_50570602_44_dialog_content = "Por favor, póngase detrás de mí, señorita Belén.",
  ui_story_5057_50570602_45_dialog_content = "Ya es suficiente, Duque. Ahora somos hombres de negocios.",
  ui_story_5057_50570602_46_dialog_content = "Jajaja, mi amigo aquí sí tiene bastante carácter.",
  ui_story_5057_50570602_47_dialog_content = "Dejaremos a ustedes dos solos. Debo decir, su amigo es bastante duro, señorita.",
  ui_story_5057_50570602_48_dialog_content = "Tsk.",
  ui_story_5057_50570602_49_dialog_content = "Increíble, el chico simplemente no se rendía.",
  ui_story_5057_50570602_50_dialog_content = "¿Está bien, Su Majestad? Lo siento, llego tarde.",
  ui_story_5057_50570602_51_dialog_content = "Estoy bien, PlayerName. No me preocupo por ese tipo de personas o acoso.",
  ui_story_5057_50570602_52_dialog_content = "Te he estado observando.",
  ui_story_5057_50570602_53_dialog_content = "¿Observándome?",
  ui_story_5057_50570602_54_dialog_content = "<color=#e8d9bb>Bethlehem coloca su mano en mi hombro.</color>",
  ui_story_5057_50570602_55_dialog_content = "Sí. El valor que mostraste fue muy encomiable.",
  ui_story_5057_50570602_56_dialog_content = "Juzgando por cómo actúan, probablemente trabajaron como ejecutores en Umbratón.",
  ui_story_5057_50570602_57_dialog_content = "Si hay un enfrentamiento, no creo que puedas vencer a ninguno de ellos, sin mencionar que estás en desventaja numérica.",
  ui_story_5057_50570602_58_dialog_content = "Ah, eso fue peligroso, ¿no? No se me pasó por la mente...",
  ui_story_5057_50570602_59_dialog_content = "Y eso es exactamente por qué eres admirado.",
  ui_story_5057_50570602_60_dialog_content = "Te has vuelto más valiente y confiable.",
  ui_story_5057_50570602_61_dialog_content = "Realmente eres el elegido.",
  ui_story_5057_50570602_62_dialog_content = "Me estás haciendo sonrojar, Su Majestad.",
  ui_story_5057_50570602_63_dialog_content = "Vale, vamos hacia la noria. Y no olvides, ahora soy Belén.",
  ui_story_5057_50570602_64_dialog_content = "<color=#e8d9bb>Entonces monto la rueda del cielo con Bethlehem... quiero decir, Belén. No puedo evitar notar que Su Majestad, que normalmente tiene una mirada helada, parece mucho más suave en sus ojos hoy.</color>",
  ui_story_5057_50570701_1_dialog_content = "Estoy nervioso.",
  ui_story_5057_50570701_2_dialog_content = "Claro, soy amigo de Su Majestad Bethlehem...",
  ui_story_5057_50570701_3_dialog_content = "Pero aún me estreso al encontrarme con ella a solas, por alguna razón...",
  ui_story_5057_50570701_4_dialog_content = "Sin mencionar que estoy representando al complejo en nombre de Lorelei...",
  ui_story_5057_50570701_5_dialog_content = "Soy presentable, ¿verdad...? Oh, he estado usando esto todo el tiempo.",
  ui_story_5057_50570701_6_dialog_content = "Entonces probablemente no traeré vergüenza a los Celestitas... Espero que no...",
  ui_story_5057_50570701_7_dialog_content = "Y, con suerte, tampoco será una vergüenza para el complejo turístico.",
  ui_story_5057_50570701_8_dialog_content = "PlayerName.",
  ui_story_5057_50570701_9_dialog_content = "Lorelei ¿no me descontaría el salario, verdad?",
  ui_story_5057_50570701_10_dialog_content = "¿PlayerName?",
  ui_story_5057_50570701_11_dialog_content = "¡Sí!",
  ui_story_5057_50570701_12_dialog_content = "¡Su Majestad!",
  ui_story_5057_50570701_13_dialog_content = "No estoy interrumpiendo nada, ¿verdad?",
  ui_story_5057_50570701_14_dialog_content = "¿Pareces preocupado?",
  ui_story_5057_50570701_15_dialog_content = "¡No, no, para nada! Ser su anfitrión siempre es un placer, Su Majestad.",
  ui_story_5057_50570701_16_dialog_content = "Lorelei se ha estado culpando a sí misma por no entretenerte antes, ya que estaba ocupada con los Eclipsites.",
  ui_story_5057_50570701_17_dialog_content = "Y espero que disfrutes de estas raras vacaciones en el complejo turístico.",
  ui_story_5057_50570701_18_dialog_content = "Ya que imagino que los asuntos del tribunal probablemente te agotaron.",
  ui_story_5057_50570701_19_dialog_content = "Ya veo. Lo aprecio.",
  ui_story_5057_50570701_20_dialog_content = "Jajaja, no importa cuántas veces monte el Dragón de la Noche Blanca, sigue siendo emocionante.",
  ui_story_5057_50570701_21_dialog_content = "Mis piernas aún están temblando ahora...",
  ui_story_5057_50570701_22_dialog_content = "Pero parece tranquilo y recogido, Su Majestad.",
  ui_story_5057_50570701_23_dialog_content = "De hecho, ya que estoy acostumbrado a montar un dragón volador.",
  ui_story_5057_50570701_24_dialog_content = "Realmente experimentaste todo, Su Majestad.",
  ui_story_5057_50570701_25_dialog_content = "Té y bocadillo para ti.",
  ui_story_5057_50570701_26_dialog_content = "Gracias, PlayerName.",
  ui_story_5057_50570701_27_dialog_content = "¿Dónde está tu porción?",
  ui_story_5057_50570701_28_dialog_content = "Oh, Lorelei le dijo al chef que preparara esto especialmente para ti.",
  ui_story_5057_50570701_29_dialog_content = "Escuché que utilizaba muchos ingredientes preciosos y costosos.",
  ui_story_5057_50570701_30_dialog_content = "¿En serio?",
  ui_story_5057_50570701_31_dialog_content = "(Hmm, no creo que Queen Bethlehem esté de muy buen ánimo.)",
  ui_story_5057_50570701_32_dialog_content = "PlayerName.",
  ui_story_5057_50570701_33_dialog_content = "¡Muy bien, Su Majestad!",
  ui_story_5057_50570701_34_dialog_content = "Tengo una pregunta.",
  ui_story_5057_50570701_35_dialog_content = "Por favor, pregunta.",
  ui_story_5057_50570701_36_dialog_content = "¿En qué rol me acompañas, PlayerName?",
  ui_story_5057_50570701_37_option_content = "Eh, ¿anfitrión del complejo turístico?",
  ui_story_5057_50570701_38_dialog_content = "Después de todo, me pagan un salario por Lorelei...",
  ui_story_5057_50570701_39_option_content = "Eh, ¿un amigo cercano de Su Majestad?",
  ui_story_5057_50570701_40_dialog_content = "Bueno, eso probablemente sea exagerado.",
  ui_story_5057_50570701_41_dialog_content = "Pero creo que puedo manejar el trabajo, ¿cierto?",
  ui_story_5057_50570701_42_dialog_content = "No creo que eso me tranquilice completamente.",
  ui_story_5057_50570701_43_dialog_content = "Gracias al destino, nos conocemos desde hace bastante tiempo, pero aún pareces preocupado por mi posición.",
  ui_story_5057_50570701_44_dialog_content = "Pero tú eres el Queen del Norte... Preferiría no ofenderte siendo demasiado informal.",
  ui_story_5057_50570701_45_dialog_content = "No, no me estás ofendiendo.",
  ui_story_5057_50570701_46_dialog_content = "Siento que la vibra en este momento está creando una brecha entre nosotros.",
  ui_story_5057_50570701_47_dialog_content = "Tu actitud me hace sentir que estoy en una función oficial.",
  ui_story_5057_50570701_48_dialog_content = "Lo siento...",
  ui_story_5057_50570701_49_dialog_content = "Por favor, no bajes la cabeza, Celestita. ¿Todavía recuerdas que eres el elegido?",
  ui_story_5057_50570701_50_dialog_content = "¡Por supuesto que sí!",
  ui_story_5057_50570701_51_dialog_content = "Si realmente quieres ayudarme a aliviar el estrés...",
  ui_story_5057_50570701_52_dialog_content = "Entonces ayúdame a olvidar mi estatus de reina y saltar esos protocolos sofocantes.",
  ui_story_5057_50570701_53_dialog_content = "Relájate, especialmente cuando solo somos los dos.",
  ui_story_5057_50570701_54_dialog_content = "Por ahora, quiero pasar el rato y relajarme contigo como amigo, PlayerName.",
  ui_story_5057_50570701_55_dialog_content = "Pero estoy un poco desanimado porque siempre me pones en un pedestal alto.",
  ui_story_5057_50570701_56_dialog_content = "Por favor, trátame solo como un amigo por el momento. Siéntete libre de bromear y hacer chistes.",
  ui_story_5057_50570701_57_dialog_content = "No me importarán los errores que puedas cometer, y esto hará que nuestras vacaciones sean mejores y nos acerquen más.",
  ui_story_5057_50570701_58_dialog_content = "Por favor, disculpa mi ignorancia. Entiendo lo que dices ahora.",
  ui_story_5057_50570701_59_dialog_content = "Comenzaré a tratarte como un amigo de ahora en adelante, Su Majestad.",
  ui_story_5057_50570701_60_dialog_content = "Está bien.",
  ui_story_5057_50570701_61_dialog_content = "(Ella está sonriendo al fin...)",
  ui_story_5057_50570701_62_dialog_content = "Supongo que puedo relajarme ahora.",
  ui_story_5057_50570701_63_dialog_content = "Oh, una cosa más.",
  ui_story_5057_50570701_64_dialog_content = "¿Qué sucede, Su Majestad?",
  ui_story_5057_50570701_65_dialog_content = "De ahora en adelante, por favor dejen de dirigirse a mí como Su Majestad o Queen.",
  ui_story_5057_50570701_66_dialog_content = "No deseo que otros invitados conozcan mi identidad.",
  ui_story_5057_50570701_67_dialog_content = "Bueno, ¿cómo lo evito...?",
  ui_story_5057_50570701_68_dialog_content = "Belén.",
  ui_story_5057_50570701_69_dialog_content = "Llámame Belén mientras esté aquí.",
  ui_story_5057_50570701_70_dialog_content = "¿Qué?",
  ui_story_5057_50570701_71_dialog_content = "<color=#e8d9bb>EveAunque Queen Bethlehem mantiene su expresión tranquila y compuesta, puedo notar que su ánimo ha mejorado bastante.</color>",
  ui_story_5057_50570702_1_dialog_content = "El cielo azul es realmente demasiado para mí...",
  ui_story_5057_50570702_2_dialog_content = "Siento que una parte de mí se arranca de mi cuerpo cada vez que me empujan y reboto hacia arriba y hacia abajo.",
  ui_story_5057_50570702_3_dialog_content = "Pero Queen Bethlehem parece estar pasándolo muy bien.",
  ui_story_5057_50570702_4_dialog_content = "Me preguntaba si podría ser peligroso para ella.",
  ui_story_5057_50570702_5_dialog_content = "Supongo que me preocupé por nada.",
  ui_story_5057_50570702_6_dialog_content = "Uf...",
  ui_story_5057_50570702_7_dialog_content = "Beth... Belén, tu cabello está desordenado.",
  ui_story_5057_50570702_8_option_content = "Ayuda a Bethlehem ordenar",
  ui_story_5057_50570702_9_dialog_content = "Por favor, permíteme echarte una mano.",
  ui_story_5057_50570702_10_dialog_content = "Seguro, gracias.",
  ui_story_5057_50570702_11_option_content = "Espera a que Bethlehem se arregle",
  ui_story_5057_50570702_12_dialog_content = "Está bien, puedo lidiar con ello yo mismo.",
  ui_story_5057_50570702_13_dialog_content = "Lo siento, casi te llamo por el nombre equivocado de nuevo.",
  ui_story_5057_50570702_14_dialog_content = "No estés nervioso, sé que tomará un tiempo acostumbrarse. Solo relájate.",
  ui_story_5057_50570702_15_dialog_content = "¡Servirá! Pareces estar de mucho mejor ánimo. ¿Disfrutaste de Cielo Azul?",
  ui_story_5057_50570702_16_dialog_content = "(Solo me recuerda a Queen Bethlehem disparando más de una docena de armas jugando ese juego de Ruleta de la Suerte.)",
  ui_story_5057_50570702_17_dialog_content = "(La probabilidad de obtener una pistola descargada en ese juego es de una en seis... Ella tiene una suerte increíble.)",
  ui_story_5057_50570702_18_dialog_content = "Este es más divertido para mí... Simplemente no tengo la oportunidad de relajarme como la gente normal, normalmente.",
  ui_story_5057_50570702_19_dialog_content = "Puedo ver eso, ya que tienes muchas cosas en tu plato como la reina.",
  ui_story_5057_50570702_20_dialog_content = "Gracias, pero no olvides que ahora soy Belén.",
  ui_story_5057_50570702_21_dialog_content = "¡Lo siento! Como disculpa, ¡disfruta de un vaso de jugo de cactus estrella por mi cuenta! Está muy delicioso.",
  ui_story_5057_50570702_22_dialog_content = "Entonces podemos ir a relajarnos en la rueda de la fortuna y pasar por alto el complejo turístico.",
  ui_story_5057_50570702_23_dialog_content = "Vuelvo enseguida.",
  ui_story_5057_50570702_24_dialog_content = "No puedo creer lo lleno que estaba el vendedor. Fue mucho tiempo de espera.",
  ui_story_5057_50570702_25_dialog_content = "Tengo que regresar. Queen Bethlehem debe estar preguntándose dónde estoy.",
  ui_story_5057_50570702_26_dialog_content = "¿Entonces qué dices, señorita?",
  ui_story_5057_50570702_27_dialog_content = "Siéntete libre de decir lo que piensas.",
  ui_story_5057_50570702_28_dialog_content = "...",
  ui_story_5057_50570702_29_dialog_content = "¿Quiénes son estos personas?",
  ui_story_5057_50570702_30_dialog_content = "Hola, amigo. ¿Tú y esta mujer joven son amigos?",
  ui_story_5057_50570702_31_dialog_content = "¿Quién eres?",
  ui_story_5057_50570702_32_dialog_content = "Perdón por la grosería. En realidad, soy un cazatalentos de Umbraton Beatitude Entertainment.",
  ui_story_5057_50570702_33_dialog_content = "Y debo decir que esta mujer joven aquí tiene una apariencia absolutamente impresionante. Es como una estrella nacida.",
  ui_story_5057_50570702_34_dialog_content = "Nuestra empresa es altamente influyente y si estás interesado en unirte a nosotros, ¡puedo presentarte algunas condiciones excepcionalmente atractivas!",
  ui_story_5057_50570702_35_dialog_content = "Estamos aquí de vacaciones y no tenemos planes de convertirnos en un ídolo o algo así.",
  ui_story_5057_50570702_36_dialog_content = "¡Sería una lástima desperdiciar un talento y potencial tan increíbles!",
  ui_story_5057_50570702_37_dialog_content = "Oye, amigo. ¿Tú y esta mujer joven son amigos?",
  ui_story_5057_50570702_38_dialog_content = "Podemos tener una discusión de tres vías, y puedo prometerte una comisión sustancial.",
  ui_story_5057_50570702_39_dialog_content = "Perdóname, pero no queremos ser molestados.",
  ui_story_5057_50570702_40_dialog_content = "Qué pena. Bueno, tendré que buscar a alguien más.",
  ui_story_5057_50570702_41_dialog_content = "Señorita, ¿puedo dejarle mi información de contacto? ¡Tengo algunas oportunidades fantásticas para ti!",
  ui_story_5057_50570702_42_dialog_content = "Por favor, sal ahora o llamaré a seguridad.",
  ui_story_5057_50570702_43_dialog_content = "Mocoso, ¿qué acabas de decir...?",
  ui_story_5057_50570702_44_dialog_content = "Por favor, póngase detrás de mí, señorita Belén.",
  ui_story_5057_50570702_45_dialog_content = "Eso es suficiente, Duque. Ahora somos hombres de negocios.",
  ui_story_5057_50570702_46_dialog_content = "Jajaja, mi amigo aquí sí tiene bastante carácter.",
  ui_story_5057_50570702_47_dialog_content = "Los dejaremos a ustedes dos solos. Debo decir, su amigo es bastante duro, señorita.",
  ui_story_5057_50570702_48_dialog_content = "Tsk.",
  ui_story_5057_50570702_49_dialog_content = "Increíble, el chico simplemente no se rendía.",
  ui_story_5057_50570702_50_dialog_content = "¿Está bien, Su Majestad? Lo siento, llegué tarde.",
  ui_story_5057_50570702_51_dialog_content = "Estoy bien, PlayerName. No me preocupo por ese tipo de personas o acoso.",
  ui_story_5057_50570702_52_dialog_content = "He estado observándote.",
  ui_story_5057_50570702_53_dialog_content = "¿Observándome?",
  ui_story_5057_50570702_54_dialog_content = "(Bethlehem pone una mano en mi hombro.)",
  ui_story_5057_50570702_55_dialog_content = "Sí. El valor que mostraste fue muy encomiable.",
  ui_story_5057_50570702_56_dialog_content = "Juzgando por cómo actúan, probablemente trabajaron como ejecutores en Umbratón.",
  ui_story_5057_50570702_57_dialog_content = "Si hay un enfrentamiento, no creo que puedas vencer a ninguno de ellos, sin mencionar que estás en desventaja numérica.",
  ui_story_5057_50570702_58_dialog_content = "Ah, eso fue peligroso, ¿no? Eso no se me pasó por la mente...",
  ui_story_5057_50570702_59_dialog_content = "Y eso es exactamente por qué eres admirado.",
  ui_story_5057_50570702_60_dialog_content = "Te has vuelto más valiente y confiable.",
  ui_story_5057_50570702_61_dialog_content = "Realmente eres el Elegido.",
  ui_story_5057_50570702_62_dialog_content = "Me estás haciendo sonrojar, Su Majestad.",
  ui_story_5057_50570702_63_dialog_content = "Vale, vamos hacia la noria. Y no olvides, ahora soy Belén.",
  ui_story_5057_50570702_64_dialog_content = "<color=#e8d9bb>Entonces monto la rueda del cielo con Bethlehem... quiero decir, Belén. No puedo evitar notar que Su Majestad, que normalmente tiene una mirada helada, parece mucho más suave en sus ojos hoy.</color>",
  ui_story_5057_50570801_1_dialog_content = "¡PlayerName!",
  ui_story_5057_50570801_2_dialog_content = "¿Eh?",
  ui_story_5057_50570801_3_dialog_content = "¡¡PlayerName!!",
  ui_story_5057_50570801_4_dialog_content = "Creo que escucho una voz perturbadora llamando mi nombre...",
  ui_story_5057_50570801_5_dialog_content = "Debería irme.",
  ui_story_5057_50570801_6_dialog_content = "PlayerName—",
  ui_story_5057_50570801_7_dialog_content = "E-Espera, no puedo seguirte el ritmo.",
  ui_story_5057_50570801_8_dialog_content = "Voy a desmayarme si sigues así—",
  ui_story_5057_50570801_9_dialog_content = "Vic¿",
  ui_story_5057_50570801_10_dialog_content = "Lo siento, presentí problemas y simplemente aceleré el paso.",
  ui_story_5057_50570801_11_dialog_content = "¿Eso es lo que piensas de mí? Eso me pone triste.",
  ui_story_5057_50570801_12_dialog_content = "Entonces, ¿por qué no lo compensas invitándome a almorzar?",
  ui_story_5057_50570801_13_dialog_content = "El extrozoólogo más famoso del mundo seguramente te honrará con su presencia.",
  ui_story_5057_50570801_14_dialog_content = "¡Deja de intentar gorrear!",
  ui_story_5057_50570801_15_dialog_content = "¿Y de qué estabas balbuceando? No soy uno de tus aprendices.",
  ui_story_5057_50570801_16_dialog_content = "¿Qué diferencia hace eso? Estoy bastante seguro de que te llevaste muy bien con Fia y Shira.",
  ui_story_5057_50570801_17_dialog_content = "No... Olvida Fia, ¿cómo podrías decirlo con Shira?",
  ui_story_5057_50570801_18_dialog_content = "Llámalo un presentimiento de maestro y no entraré en los detalles específicos.",
  ui_story_5057_50570801_19_dialog_content = "Entonces, ¿alguna vez has considerado llevar la relación un paso más allá?",
  ui_story_5057_50570801_20_dialog_content = "Entonces todos seremos una familia y tú también tendrás que llamarme \"Maestro\".",
  ui_story_5057_50570801_21_dialog_content = "¿Quién crees que es mejor para ti, Fia o Shira?",
  ui_story_5057_50570801_22_option_content = "¡Las Bestias Maravillosas!",
  ui_story_5057_50570801_23_dialog_content = "Oye, no esperaba que tú tuvieras un interés común.",
  ui_story_5057_50570801_24_dialog_content = "Algunas criaturas son tan grandiosas como yo, no solo en personalidad sino también en el mismo hermoso color...",
  ui_story_5057_50570801_25_dialog_content = "¿Te refieres a ese boros cualquiera que encontramos antes?",
  ui_story_5057_50570801_26_dialog_content = "Exactamente. Por favor, consulta mi nuevo libro, \"El Misterio Entre Yo y Ouroboros\" para más detalles.",
  ui_story_5057_50570801_27_dialog_content = "Todavía estoy trabajando en ello, así que puedes esperarlo con ansias por ahora.",
  ui_story_5057_50570801_28_dialog_content = "Hablando de eso, ¿también te cautivó su encantadora figura?",
  ui_story_5057_50570801_29_dialog_content = "¡Vamos, embarquémonos en los senderos de Ouroboros y convirtámonos en supremos extrozoólogos!",
  ui_story_5057_50570801_30_dialog_content = "No, gracias, ¡solo estaba bromeando!",
  ui_story_5057_50570801_31_dialog_content = "¿Y qué pasa con lo supremo de repente?",
  ui_story_5057_50570801_32_dialog_content = "¡Por favor, detén las suposiciones locas!",
  ui_story_5057_50570801_33_dialog_content = "¡Iré con el Maestro Vic!",
  ui_story_5057_50570801_34_option_content = "¡Elige Maestro Vic!",
  ui_story_5057_50570801_35_dialog_content = "...",
  ui_story_5057_50570801_36_dialog_content = "Eh...",
  ui_story_5057_50570801_37_dialog_content = "...",
  ui_story_5057_50570801_38_dialog_content = "Espera, ¿qué tipo de expresión es esa?",
  ui_story_5057_50570801_39_dialog_content = "Está bien, solo estoy conmovido hasta las lágrimas.",
  ui_story_5057_50570801_40_dialog_content = "Eso es lo que quería saber. ¿Por qué estás llorando?",
  ui_story_5057_50570801_41_dialog_content = "No pensé que te abrirías a mí de esa manera, PlayerName.",
  ui_story_5057_50570801_42_dialog_content = "La emoción y pasión que me mostraste...",
  ui_story_5057_50570801_43_dialog_content = "Me conmovió mucho.",
  ui_story_5057_50570801_44_dialog_content = "¿No puedes darte cuenta de que me estoy burlando de ti? No, debes estar fingiendo.",
  ui_story_5057_50570801_45_dialog_content = "Lamentablemente, hice un juramento.",
  ui_story_5057_50570801_46_dialog_content = "Pasaré toda mi vida con bestias maravillosas. ¿No es cierto, pequeña bola de pelo?",
  ui_story_5057_50570801_47_dialog_content = "¡Chirrido!",
  ui_story_5057_50570801_48_dialog_content = "¿Qué? ¿Dijiste que los Celestitas son bestias maravillosas en cierto sentido?",
  ui_story_5057_50570801_49_dialog_content = "¿Entonces él está dentro de mi rango de opciones?",
  ui_story_5057_50570801_50_dialog_content = "También serás feliz, ¿si estoy con PlayerName?",
  ui_story_5057_50570801_51_dialog_content = "Solo fue un trino... ¿Cómo pudiste sacar tanto de eso?",
  ui_story_5057_50570801_52_dialog_content = "Ahora creo que me estás tomando el pelo.",
  ui_story_5057_50570801_53_dialog_content = "Jejeje, es broma.",
  ui_story_5057_50570801_54_dialog_content = "Y eso definitivamente no puede pasar por encima de la cabeza del astuto PlayerName, ¿cierto?",
  ui_story_5057_50570801_55_dialog_content = "Ja, tanto el maestro como los aprendices son difíciles de tratar.",
  ui_story_5057_50570801_56_dialog_content = "Entonces, ¿qué quieres de mí, ya que probablemente no estás aquí solo para charlar?",
  ui_story_5057_50570801_57_dialog_content = "¡Sabía que eras un francotirador!",
  ui_story_5057_50570801_58_dialog_content = "Esa es una corazonada que tengo por haber tratado contigo y tus aprendices muchas veces.",
  ui_story_5057_50570801_59_dialog_content = "¡No esperemos entonces! Rápido, a la ecozona.",
  ui_story_5057_50570801_60_dialog_content = "¿Ecozona?",
  ui_story_5057_50570801_61_dialog_content = "¡Deja de arrastrarme! ¿Por qué tú y Fia hacen eso todo el tiempo?",
  ui_story_5057_50570801_62_dialog_content = "<color=#e8d9bb>En nuestro camino, Vic me invitó a un delicioso helado.</color>",
  ui_story_5057_50570801_63_dialog_content = "<color=#e8d9bb>Sin embargo, solo después de terminar me dijo que había olvidado su billetera...</color>",
  ui_story_5057_50570802_1_dialog_content = "Ah, el helado no está mal.",
  ui_story_5057_50570802_2_dialog_content = "¡Gracias por el detalle, PlayerName!",
  ui_story_5057_50570802_3_dialog_content = "No puedo creer que tengas el descaro de decir eso.",
  ui_story_5057_50570802_4_dialog_content = "Afortunadamente, Vice puso algo de cambio para gastar en mi bolsillo.",
  ui_story_5057_50570802_5_dialog_content = "De lo contrario, estaríamos sin suerte.",
  ui_story_5057_50570802_6_dialog_content = "Tienes suerte, PlayerName, de que Vice te cuide y te dé dinero.",
  ui_story_5057_50570802_7_dialog_content = "Todo lo que mis aprendices saben hacer es extorsionarme.",
  ui_story_5057_50570802_8_dialog_content = "Pero, ¿no les das órdenes a ellos todo el día también?",
  ui_story_5057_50570802_9_dialog_content = "Lo que va, vuelve.",
  ui_story_5057_50570802_10_dialog_content = "Eso no es mandarlos. Se llama entrenamiento.",
  ui_story_5057_50570802_11_dialog_content = "Sin el entrenamiento sin tiempo libre durante todo el año que organicé para ellos, no serían tan notables tan pronto.",
  ui_story_5057_50570802_12_dialog_content = "Qué mentiroso...",
  ui_story_5057_50570802_13_dialog_content = "Jajaja... No importa eso, ya estamos acá.",
  ui_story_5057_50570802_14_dialog_content = "¿Es esta la ecozona?",
  ui_story_5057_50570802_15_dialog_content = "¡Hiya!",
  ui_story_5057_50570802_16_dialog_content = "¡Hiya!",
  ui_story_5057_50570802_17_dialog_content = "gloo...",
  ui_story_5057_50570802_18_dialog_content = "¿No son Bica y Glooey?",
  ui_story_5057_50570802_19_dialog_content = "No esperaba verlos aquí en absoluto.",
  ui_story_5057_50570802_20_dialog_content = "Francamente, yo tampoco pensaba que podrían sobrevivir aquí.",
  ui_story_5057_50570802_21_dialog_content = "Bica generalmente prefiere vivir en montañas aisladas.",
  ui_story_5057_50570802_22_dialog_content = "Y a Glooey le encantaban los hábitats con abundantes fuentes de agua.",
  ui_story_5057_50570802_23_dialog_content = "Even cuando se informaron avistamientos de Glooey en áreas secas, ya se habían ido cuando llegamos allí.",
  ui_story_5057_50570802_24_dialog_content = "Fia no estaba la última vez, y me esforcé sin parar durante tres días para alcanzarlo.",
  ui_story_5057_50570802_25_dialog_content = "Peiné todo el lugar durante un día entero, luego acampé durante otras dos semanas solo porque sí.",
  ui_story_5057_50570802_26_dialog_content = "Estaba tan apurado que olvidé traer equipo de campamento, así que dormí con la pequeña bola de pelo en mis brazos todas las noches.",
  ui_story_5057_50570802_27_dialog_content = "No regresé hasta que estuve absolutamente seguro de que no se mostraría ningún Glooey.",
  ui_story_5057_50570802_28_dialog_content = "Qué trabajo tan difícil tienes...",
  ui_story_5057_50570802_29_dialog_content = "Nah, no es nada.",
  ui_story_5057_50570802_30_dialog_content = "Todo en un día de trabajo de un extrozoólogo.",
  ui_story_5057_50570802_31_dialog_content = "No dejaba de recordarle a Fia que se preparara antes de salir, pero siempre me olvidaba cuando se trataba de mí mismo.",
  ui_story_5057_50570802_32_option_content = "MayYo puedo ayudar con eso.",
  ui_story_5057_50570802_33_dialog_content = "Avísame antes de irte de viaje largo. Si el tiempo lo permite, Soroz puede llevarte allí.",
  ui_story_5057_50570802_34_dialog_content = "Y puedes guardar algo de equipo en Soroz para que no lo olvides.",
  ui_story_5057_50570802_35_dialog_content = "Hmm... qué buena idea.",
  ui_story_5057_50570802_36_dialog_content = "Eso es muy considerado de tu parte, PlayerName.",
  ui_story_5057_50570802_37_option_content = "Envía Fia la próxima vez",
  ui_story_5057_50570802_38_dialog_content = "Tienes razón, jaja.",
  ui_story_5057_50570802_39_dialog_content = "¡Mi cuerpo es demasiado viejo para soportar la tortura!",
  ui_story_5057_50570802_40_dialog_content = "Es mejor que me quede en casa, trabaje en mi jardín y cuide a las pequeñas criaturas.",
  ui_story_5057_50570802_41_dialog_content = "Pero era urgente en ese momento, ya que el Glooey que aparecía en las tierras secas podría ser una subespecie rara.",
  ui_story_5057_50570802_42_dialog_content = "Si pudiera documentarlos, podría hacer que las personas los entiendan y los amen más...",
  ui_story_5057_50570802_43_dialog_content = "gloo...",
  ui_story_5057_50570802_44_dialog_content = "Por supuesto, Buck también es muy especial.",
  ui_story_5057_50570802_45_dialog_content = "Every Glooey es único para mí.",
  ui_story_5057_50570802_46_dialog_content = "gloo...",
  ui_story_5057_50570802_47_dialog_content = "gloo...",
  ui_story_5057_50570802_48_dialog_content = "Maestro Vic, ¿las Glooey y Bica que habitan en el Desierto de Rediesel también son especies especiales?",
  ui_story_5057_50570802_49_dialog_content = "No, no lo están.",
  ui_story_5057_50570802_50_dialog_content = "Fueron abandonados en el Desierto de Reddiesel.",
  ui_story_5057_50570802_51_dialog_content = "¡¿Qué?!",
  ui_story_5057_50570802_52_dialog_content = "Sí, supongo que los chicos que traficaban con bestias maravillosas son los responsables.",
  ui_story_5057_50570802_53_dialog_content = "No sé por qué todavía. Maytal vez no pudieron obtener el precio que querían o lo que sea.",
  ui_story_5057_50570802_54_dialog_content = "Pero esas cosas terribles simplemente dejaron a las bestias donde tenían dificultades para sobrevivir...",
  ui_story_5057_50570802_55_dialog_content = "gloo...",
  ui_story_5057_50570802_56_dialog_content = "Tengo un favor que pedirte, PlayerName.",
  ui_story_5057_50570802_57_dialog_content = "Entiendo cómo hablan algunas de las bestias maravillosas, pero no puedo comprender realmente lo que piensan.",
  ui_story_5057_50570802_58_dialog_content = "¿Puedes usar tu habilidad psíquica en ellos y convencerlos de que me digan quién hizo esto?",
  ui_story_5057_50570802_59_dialog_content = "Debo obtener justicia para ellos.",
  ui_story_5057_50570802_60_dialog_content = "Entiendo.",
  ui_story_5057_50570802_61_dialog_content = "Gloo... Sr. Vic...",
  ui_story_5057_50570802_62_dialog_content = "Puedo escucharlo ahora... Dime, ¿quién te hizo esto y a qué pandilla pertenecen?",
  ui_story_5057_50570802_63_dialog_content = "Esa persona era... Gloo...",
  ui_story_5057_50570802_64_dialog_content = "Fue Bica...",
  ui_story_5057_50570802_65_dialog_content = "Así que estábamos pidiendo aventón en el dirigible...",
  ui_story_5057_50570802_66_dialog_content = "Pero Bica arruinó las cosas... Y ahora terminamos cayendo aquí.",
  ui_story_5057_50570802_67_dialog_content = "¡Hiya!",
  ui_story_5057_50570802_68_dialog_content = "OK...",
  ui_story_5057_50570802_69_dialog_content = "Parece que obtuviste tu respuesta, Vic.",
  ui_story_5057_50570802_70_dialog_content = "Sí, todo está bien y perfecto ahora.",
  ui_story_5057_50570802_71_dialog_content = "¿Quién sabe? Tal vez incluso me deshice de algunos en esa banda de criminales inadvertidamente antes.",
  ui_story_5057_50570802_72_dialog_content = "Cuanto más, mejor. Después de todo, son criminales.",
  ui_story_5057_50570802_73_dialog_content = "Ahora entiendo por qué a Fia le encantaba ir de aventuras contigo, PlayerName.",
  ui_story_5057_50570802_74_dialog_content = "Eve¿Consideraste seguirme?",
  ui_story_5057_50570802_75_dialog_content = "Puedo encontrar un Kyllo para ti...",
  ui_story_5057_50570802_76_dialog_content = "¡Deja de molestarme!",
  ui_story_5057_50570802_77_dialog_content = "<color=#e8d9bb>Y entonces, Vic sigue molestandome hasta que no lo soporto y firmo algunos tratados desiguales.</color>",
  ui_story_5057_50570901_1_dialog_content = "Casi llegas tarde, PlayerName.",
  ui_story_5057_50570901_2_dialog_content = "Huff, huff... Lo siento... pero tú me enviaste el mensaje hace unos minutos.",
  ui_story_5057_50570901_3_dialog_content = "Corrí a toda velocidad hasta aquí...",
  ui_story_5057_50570901_4_dialog_content = "Bien, eso es cierto.",
  ui_story_5057_50570901_5_dialog_content = "Es mi culpa llamarte tan repentinamente. No debería culparte y me disculpo.",
  ui_story_5057_50570901_6_dialog_content = "Pero lograste correr hasta aquí... Parece que te has vuelto mucho más fuerte que antes.",
  ui_story_5057_50570901_7_dialog_content = "EveDesde que salí del subterráneo, las cosas nunca dejan de suceder, a veces incluso peligrosas.",
  ui_story_5057_50570901_8_dialog_content = "Ser perseguido por diferentes Eclipsites durante todo el año haría que cualquiera esté en forma.",
  ui_story_5057_50570901_9_dialog_content = "También escuché que ahora eres una pareja adecuada para los Eclipsites comunes.",
  ui_story_5057_50570901_10_dialog_content = "TakiTeniendo en cuenta tus habilidades psíquicas, tal vez algún día superes a los Aurorians como guerrero.",
  ui_story_5057_50570901_11_dialog_content = "De ninguna manera, todavía me queda un largo camino por recorrer. Me gustaría ser lo suficientemente fuerte para proteger a todos, pero aún no lo estoy.",
  ui_story_5057_50570901_12_dialog_content = "Astuto y humilde ahora... Estoy impresionado.",
  ui_story_5057_50570901_13_dialog_content = "Basta de charlas, ahora la razón específica por la que quiero verte.",
  ui_story_5057_50570901_14_dialog_content = "¿Me pones a trabajar ahora? Estaba buscando ganar más tiempo hablando...",
  ui_story_5057_50570901_15_dialog_content = "No te quejes.",
  ui_story_5057_50570901_16_dialog_content = "Recientemente conseguí un trabajo con alguien que tiene información sobre los contrabandistas en Umbratón y está incógnito entre los invitados en el complejo Denuo Valley Resort.",
  ui_story_5057_50570901_17_dialog_content = "Es un vendedor de información muy astuto y bien conectado. Eludió a todos los que enviaron para seguirlo o atraparlo.",
  ui_story_5057_50570901_18_dialog_content = "Pero es diferente para mí. Como rara vez tomo este tipo de trabajo, él no me reconocerá.",
  ui_story_5057_50570901_19_dialog_content = "¿Lo tomaste porque el dinero se está volviendo escaso?",
  ui_story_5057_50570901_20_dialog_content = "No hagas comentarios sobre mi situación financiera, a menos que quieras que te venda al mercado negro.",
  ui_story_5057_50570901_21_dialog_content = "¡Lo siento! Por favor continua.",
  ui_story_5057_50570901_22_dialog_content = "Según mi empleador, el vendedor ambulante tiene un talento especial para detectar la llegada de grupos hostiles.",
  ui_story_5057_50570901_23_dialog_content = "Entonces, debemos apostarnos y esperar a que él aparezca aquí.",
  ui_story_5057_50570901_24_dialog_content = "Necesito tu ayuda para cubrir todas las bases.",
  ui_story_5057_50570901_25_dialog_content = "Finge ser mi cita, ¿entendido?",
  ui_story_5057_50570901_26_dialog_content = "Entiendo, él podía percibir partes hostiles...",
  ui_story_5057_50570901_27_dialog_content = "... así que seré tu cita... ¿Cita?!",
  ui_story_5057_50570901_28_dialog_content = "Oh, ¿qué pasa, querida?",
  ui_story_5057_50570901_29_dialog_content = "¡QUERIDA!",
  ui_story_5057_50570901_30_option_content = "¡Sí! ¿Qué ocurre?",
  ui_story_5057_50570901_31_dialog_content = "Nada. Solo recuerda tu papel y deja de distraerte.",
  ui_story_5057_50570901_32_option_content = "...",
  ui_story_5057_50570901_33_dialog_content = "¡PlayerName!",
  ui_story_5057_50570901_34_dialog_content = "¡Sí!",
  ui_story_5057_50570901_35_dialog_content = "Lo siento, no estoy acostumbrado a esto...",
  ui_story_5057_50570901_36_dialog_content = "No te disculpes. Solo es un trabajo.",
  ui_story_5057_50570901_37_dialog_content = "Pero aún así, mantén la cabeza fría. Si el objetivo está cerca, necesitaré tu poder para localizar su posición.",
  ui_story_5057_50570901_38_dialog_content = "Actúa natural... Si se da cuenta de que lo han descubierto, podría haber personas inocentes heridas.",
  ui_story_5057_50570901_39_dialog_content = "Solo necesitas concentrarte en la tarea que tienes entre manos. Aquí.",
  ui_story_5057_50570901_40_dialog_content = "¿Qué es esto?",
  ui_story_5057_50570901_41_dialog_content = "Protector solar.",
  ui_story_5057_50570901_42_dialog_content = "Sé que es protector solar... Pero, eh...",
  ui_story_5057_50570901_43_dialog_content = "¿Quieres actuar incómodo y atraer atención no deseada?",
  ui_story_5057_50570901_44_dialog_content = "¡Claro que no!",
  ui_story_5057_50570901_45_dialog_content = "¿Quieres que me queme con el sol, entonces?",
  ui_story_5057_50570901_46_dialog_content = "<color=#e8d9bb>Por un breve momento, quedo cautivado mientras la espalda de Paloma, tan blanca como la nieve, parece irradiar un resplandor brillante bajo la luz solar.</color>",
  ui_story_5057_50570901_47_dialog_content = "Lo primero es lo primero, te pagaré lo que ya acordamos. Ponerme protector solar no te hará ganar una bonificación.",
  ui_story_5057_50570901_48_dialog_content = "No me refería a eso...! Nunca lo he hecho antes, así que...",
  ui_story_5057_50570901_49_dialog_content = "¿Entonces, estás alucinando?",
  ui_story_5057_50570901_50_dialog_content = "¡De ninguna manera! ¡Te lo frotaré!",
  ui_story_5057_50570901_51_dialog_content = "Ahí vamos, eso es mejor.",
  ui_story_5057_50570901_52_dialog_content = "¿Por qué tiemblas? Sé serio y asegúrate de aplicarlo de manera uniforme.",
  ui_story_5057_50570901_53_dialog_content = "¡Bien bien!",
  ui_story_5057_50570901_54_dialog_content = "Mientras tanto, mantén tus ojos en esa dirección por si ves algo sospechoso.",
  ui_story_5057_50570901_55_dialog_content = "¡Sí!",
  ui_story_5057_50570901_56_dialog_content = "(Vaya, mi corazón late a mil por hora.)",
  ui_story_5057_50570901_57_dialog_content = "¿Por qué te detienes—",
  ui_story_5057_50570901_58_dialog_content = "¡Creo que hay alguien sospechoso por allá!",
  ui_story_5057_50570901_59_dialog_content = "Ese es él. Lo tengo.",
  ui_story_5057_50570901_60_dialog_content = "<color=#e8d9bb>EveAunque Paloma y yo hemos atrapado al vendedor ambulante de información, mis manos siguen temblando.</color>",
  ui_story_5057_50570902_1_dialog_content = "¿Soy el anfitrión de Paloma de nuevo hoy?",
  ui_story_5057_50570902_2_dialog_content = "Después de lo que pasó la última vez, no creo que pueda enfrentarme a ella.",
  ui_story_5057_50570902_3_dialog_content = "Qué dilema... Todavía lo veo cuando cierro mis ojos.",
  ui_story_5057_50570902_4_dialog_content = "Hola, PlayerName, te traje una bebida.",
  ui_story_5057_50570902_5_dialog_content = "No, no, deja de preguntarte.",
  ui_story_5057_50570902_6_dialog_content = "...",
  ui_story_5057_50570902_7_dialog_content = "¡PlayerName!",
  ui_story_5057_50570902_8_dialog_content = "¡Oh, hola, Paloma!",
  ui_story_5057_50570902_9_dialog_content = "¿Qué haces soñando despierto de nuevo? ¡Ten cuidado o unos malhechores te secuestrarán y te venderán en la tienda de mascotas!",
  ui_story_5057_50570902_10_dialog_content = "No puede ser tan malo, ¿verdad? Gracias por la bebida... *trago*",
  ui_story_5057_50570902_11_dialog_content = "Puse sedantes en ello.",
  ui_story_5057_50570902_12_dialog_content = "<size=50>¡Pfft—!</size>",
  ui_story_5057_50570902_13_dialog_content = "Jajaja, solo bromeo.",
  ui_story_5057_50570902_14_dialog_content = "Eso no es gracioso...",
  ui_story_5057_50570902_15_dialog_content = "Ejem... Entonces, sobre la última vez... No quería...",
  ui_story_5057_50570902_16_dialog_content = "¿Última vez? ¿Qué quieres decir?",
  ui_story_5057_50570902_17_dialog_content = "Sabes, cuando te ayudé a atrapar a ese chico...",
  ui_story_5057_50570902_18_dialog_content = "Oh, estás hablando de ponerme protector solar—",
  ui_story_5057_50570902_19_dialog_content = "¡No tan alto, por favor!",
  ui_story_5057_50570902_20_dialog_content = "<color=#e8d9bb>Paloma levanta una ceja, mirándome con un brillo juguetón en sus ojos.</color>",
  ui_story_5057_50570902_21_dialog_content = "¿Crees que me enojaría contigo por eso?",
  ui_story_5057_50570902_22_dialog_content = "No... Porque... Yo...",
  ui_story_5057_50570902_23_dialog_content = "¿Te disculpas por sentirte incómodo al aplicar protector solar o por el acto de aplicarme protector solar a mí?",
  ui_story_5057_50570902_24_dialog_content = "Si es lo último, puedes parar ya que te pedí que lo hicieras.",
  ui_story_5057_50570902_25_dialog_content = "Je, supongo que aún eres inocente de corazón, PlayerName.",
  ui_story_5057_50570902_26_dialog_content = "Si cosas pequeñas como esta te hacen entrar en pánico, ¿qué sucede si la próxima vez tiene que ser más íntimo?",
  ui_story_5057_50570902_27_dialog_content = "¿Como algo más privado?",
  ui_story_5057_50570902_28_dialog_content = "No creo que haya una próxima vez...",
  ui_story_5057_50570902_29_dialog_content = "Y no me pedirías hacer algo más íntimo, ¿verdad?",
  ui_story_5057_50570902_30_dialog_content = "¿Oh? Entonces, ¿cuál es tu idea de \"intimidad\"?",
  ui_story_5057_50570902_31_dialog_content = "¡T-Tú sabes, eso!",
  ui_story_5057_50570902_32_dialog_content = "¿Eh?",
  ui_story_5057_50570902_33_option_content = "Tú me... obligarías a...",
  ui_story_5057_50570902_34_dialog_content = "Jajaja, nunca te dejaré ir demasiado lejos.",
  ui_story_5057_50570902_35_option_content = "Yo... ¡No sé!",
  ui_story_5057_50570902_36_dialog_content = "<color=#e8d9bb>Paloma me despeina con su mano.</color>",
  ui_story_5057_50570902_37_dialog_content = "¡El trabajo sería un fracaso épico si te desmayaras por modestia!",
  ui_story_5057_50570902_38_dialog_content = "Oh...",
  ui_story_5057_50570902_39_dialog_content = "Sinceramente, sin embargo, no me importaría si el trabajo lo requiriera.",
  ui_story_5057_50570902_40_dialog_content = "Solo es un trabajo. No me digas que lo tomarás en serio, PlayerName.",
  ui_story_5057_50570902_41_dialog_content = "Bueno...",
  ui_story_5057_50570902_42_dialog_content = "Oh, para evitar posibles problemas durante un trabajo y la necesidad de descontar de tu salario...",
  ui_story_5057_50570902_43_dialog_content = "Ensayemos para que te acostumbres.",
  ui_story_5057_50570902_44_option_content = "¿Q-Qué?",
  ui_story_5057_50570902_45_dialog_content = "Es una broma. ¿Pensabas que iba en serio?",
  ui_story_5057_50570902_46_dialog_content = "¡Eres realmente inocente!",
  ui_story_5057_50570902_47_dialog_content = "Puaj-!",
  ui_story_5057_50570902_48_option_content = "¡Por favor, córtalo!",
  ui_story_5057_50570902_49_dialog_content = "Jajaja, lo siento.",
  ui_story_5057_50570902_50_dialog_content = "Mmm, ¿ahora qué?",
  ui_story_5057_50570902_51_dialog_content = "No pareces contento.",
  ui_story_5057_50570902_52_dialog_content = "¿Estás haciendo un berrinche porque te molesté?",
  ui_story_5057_50570902_53_dialog_content = "¿Qué tal si peleas conmigo, entonces?",
  ui_story_5057_50570902_54_dialog_content = "¿Luchar contigo?",
  ui_story_5057_50570902_55_dialog_content = "Eso es correcto. Si ganas, haré cualquier cosa que quieras por un día. Por supuesto, eso incluye lo que mencioné antes.",
  ui_story_5057_50570902_56_dialog_content = "Si pierdes, vendrás a trabajar conmigo en el Café de las Monjas, y también me quedo con tu salario.",
  ui_story_5057_50570902_57_dialog_content = "Espera... ¿Qué es una Cafetería de Monjas? ¡Eso suena raro!",
  ui_story_5057_50570902_58_dialog_content = "Es una larga historia. Era una noche fría.",
  ui_story_5057_50570902_59_dialog_content = "Al cruzar una calle en Umbratón, el viento frío azotó mi cuerpo.",
  ui_story_5057_50570902_60_dialog_content = "Me esforzaba por masticar y tragar un último bocado de mi última bola de arroz.",
  ui_story_5057_50570902_61_dialog_content = "¿Cómo llegaste a ese punto...",
  ui_story_5057_50570902_62_dialog_content = "La venganza exige grandes capitales, PlayerName.",
  ui_story_5057_50570902_63_dialog_content = "Una amable monja me presentó y me consiguió un trabajo a tiempo parcial en una cafetería.",
  ui_story_5057_50570902_64_dialog_content = "Esos fueron días felices. Incluso olvidé la venganza, hasta que un día.",
  ui_story_5057_50570902_65_dialog_content = "<size=50>Ah—por favor deténgase, señor.</size>",
  ui_story_5057_50570902_66_dialog_content = "Tsk, tsk, tsk... ¿te das cuenta de cuántas formas se puede interpretar el Versículo 50 en el Capítulo 11, Volumen 7 de los Preceptos de la Iglesia de la Noche Blanca?",
  ui_story_5057_50570902_67_dialog_content = "P-Por favor, suéltame...",
  ui_story_5057_50570902_68_dialog_content = "Por favor deténgalo, señor.",
  ui_story_5057_50570902_69_dialog_content = "Oh, es tú.",
  ui_story_5057_50570902_70_dialog_content = "Soy yo, Mirren. Grabé todo lo que acabas de hacer.",
  ui_story_5057_50570902_71_dialog_content = "¡Dame diez mil millones de Nightium o sufre!",
  ui_story_5057_50570902_72_dialog_content = "¿Qué? ¿No puedo simplemente disculparse?",
  ui_story_5057_50570902_73_dialog_content = "Esa no es una opción. He apostado mi vida desde la infancia hasta ahora en buscar venganza contra ti. ¿Cómo podría ser suficiente una disculpa?",
  ui_story_5057_50570902_74_dialog_content = "¡Rayos, me largo de aquí!",
  ui_story_5057_50570902_75_dialog_content = "Me salvaste, Paloma... Ahora soy tuyo para siempre...",
  ui_story_5057_50570902_76_dialog_content = "Gracias pero no gracias.",
  ui_story_5057_50570902_77_dialog_content = "No necesito un Celestita. Lo que necesito es un verdugo que pueda acompañarme en mi venganza.",
  ui_story_5057_50570902_78_dialog_content = "¿Por qué estoy yo y Mirren en la historia?",
  ui_story_5057_50570902_79_dialog_content = "Así es como va. De todos modos, si pierdes, trabajarás conmigo.",
  ui_story_5057_50570902_X80_dialog_content = "<color=#e8d9bb>Paloma lanzó un desafío de pesca, y yo estaba como, \"¡Oh, definitivamente voy a ganar esto!\"</color>",
  ui_story_5057_50570902_80_dialog_content = "<color=#e8d9bb>Entonces, para familiarizarme con las cosas en Habit Café, comencé a memorizar los principios de la Iglesia de Lumopolis.</color>",
  ui_story_5057_50571001_1_dialog_content = "¡Buenos días, PlayerName!",
  ui_story_5057_50571001_2_dialog_content = "Buenos días, Vice.",
  ui_story_5057_50571001_3_dialog_content = "¿A dónde vas con todo ese equipaje?",
  ui_story_5057_50571001_4_dialog_content = "Estas son algunas herramientas para reparación y mantenimiento.",
  ui_story_5057_50571001_5_dialog_content = "Lorelei me dijo que algunas atracciones no funcionaban bien y me pidió que las arreglara.",
  ui_story_5057_50571001_6_dialog_content = "Entiendo, pero ¿no sería mejor dejarlo en manos de los chicos de Rediesel Wrench?",
  ui_story_5057_50571001_7_dialog_content = "Sí, pero se fueron en un coche a quién-sabe-dónde hace unos días.",
  ui_story_5057_50571001_8_dialog_content = "No se ha sabido de ellos desde entonces. Supongo que ellos...",
  ui_story_5057_50571001_9_dialog_content = "Puedo adivinar bastante bien lo que estás adivinando.",
  ui_story_5057_50571001_10_dialog_content = "Sí. Lorelei también hizo una oferta muy generosa!",
  ui_story_5057_50571001_11_dialog_content = "¡Después de esto, nos nivelaremos para el mes!",
  ui_story_5057_50571001_12_dialog_content = "¿Tienes planes para el día, PlayerName?",
  ui_story_5057_50571001_13_dialog_content = "Eh... (No hay forma de que pueda decir que quiero tomar el sol y pescar...)",
  ui_story_5057_50571001_14_dialog_content = "Realmente no, entonces, ¿por qué no voy contigo?",
  ui_story_5057_50571001_15_dialog_content = "¡Seré tu ayudante por el día!",
  ui_story_5057_50571001_16_dialog_content = "¡Genial, contaré contigo entonces!",
  ui_story_5057_50571001_17_dialog_content = "Seguro. ¡Déjame ayudarte a cargar las herramientas!",
  ui_story_5057_50571001_18_dialog_content = "La estructura completa parece lo suficientemente estable, así que es solo que este tornillo de respaldo se ha aflojado un poco.",
  ui_story_5057_50571001_19_dialog_content = "Ayúdame a apretar el tornillo, PlayerName.",
  ui_story_5057_50571001_20_dialog_content = "¡Lo tienes!",
  ui_story_5057_50571001_21_dialog_content = "Está bien. ¡Aquí vamos!",
  ui_story_5057_50571001_22_dialog_content = "¡Hiya!",
  ui_story_5057_50571001_23_dialog_content = "Por favor, pásame eso.",
  ui_story_5057_50571001_24_dialog_content = "¿Te refieres al lubricante? ¡Aquí, todo listo para ir!",
  ui_story_5057_50571001_25_dialog_content = "Me lees muy bien, PlayerName.",
  ui_story_5057_50571001_26_dialog_content = "Excelente en cuanto a un ayudante se refiere.",
  ui_story_5057_50571001_27_dialog_content = "Por supuesto. Hemos estado juntos por tanto tiempo que tenemos una gran química.",
  ui_story_5057_50571001_28_dialog_content = "Vale, todo listo.",
  ui_story_5057_50571001_29_dialog_content = "Este es el último lugar para revisar.",
  ui_story_5057_50571001_30_dialog_content = "Podemos regresar después de empacar las herramientas.",
  ui_story_5057_50571001_31_dialog_content = "¡Maravilloso!",
  ui_story_5057_50571001_32_dialog_content = "Este mantenimiento es aún más suave de lo que imaginaba.",
  ui_story_5057_50571001_33_dialog_content = "Y no esperaba que las atracciones diseñadas por Rediesel Wrench tuvieran cierta calidad estética.",
  ui_story_5057_50571001_34_dialog_content = "La estructura puede ser simple, pero el ingenio que se empleó en ella permitió que se pudiera mantener a un bajo costo de mantenimiento.",
  ui_story_5057_50571001_35_dialog_content = "Después de todo, hay muchos mecánicos increíbles en Rediesel Wrench.",
  ui_story_5057_50571001_36_dialog_content = "La capacidad de hacer uso de los recursos disponibles es probablemente una de las razones por las que son tan buenos para sobrevivir.",
  ui_story_5057_50571001_37_dialog_content = "Mm, aprendí mucho de ellos hoy. Illumina podría tomar una página o dos de su libro.",
  ui_story_5057_50571001_38_dialog_content = "¡Ese es el Vice que conozco, siempre pensando en aprender y absorber algo nuevo!",
  ui_story_5057_50571001_39_dialog_content = "¿Por qué el cumplido repentino?",
  ui_story_5057_50571001_40_dialog_content = "Como tu amigo, por supuesto, necesito seguir aprendiendo y volviéndome más fuerte para protegerte a ti y a Soroz.",
  ui_story_5057_50571001_41_option_content = "Estoy conmovido...",
  ui_story_5057_50571001_42_option_content = "Vice...",
  ui_story_5057_50571001_43_dialog_content = "Oye, ¿por qué estás llorando?",
  ui_story_5057_50571001_44_dialog_content = "Oh, solo me conmovió, eso es todo.",
  ui_story_5057_50571001_45_dialog_content = "Pensando en retrospectiva, la primera vez que te conocí fue cuando accidentalmente destruiste el suelo...",
  ui_story_5057_50571001_46_dialog_content = "¡Ahora te has vuelto tan confiable...!",
  ui_story_5057_50571001_47_dialog_content = "¡Alto ahí! ¡No vuelvas a mencionar esa vergüenza de nuevo!",
  ui_story_5057_50571001_48_dialog_content = "Estás exagerando demasiado, PlayerName. Todo el mundo está mejorando constantemente, y eso te incluye a ti.",
  ui_story_5057_50571001_49_dialog_content = "¿Crecí? Seguro que no lo sentí...",
  ui_story_5057_50571001_50_dialog_content = "Ese es el pensamiento equivocado y apestoso. Te vi mejorar con mis propios ojos.",
  ui_story_5057_50571001_51_dialog_content = "Hasta el punto en que no puedo imaginar sin ti cerca...",
  ui_story_5057_50571001_52_dialog_content = "Gruñido...",
  ui_story_5057_50571001_53_dialog_content = "¡Lo siento, fui yo! Tenía prisa por venir a ayudarte, ¡me salté el desayuno!",
  ui_story_5057_50571001_54_dialog_content = "Déjame revisar... ¡Es cierto, ya es bastante tarde!",
  ui_story_5057_50571001_55_dialog_content = "¡Ven a almorzar conmigo, PlayerName!",
  ui_story_5057_50571001_56_dialog_content = "<size=30>Uh, no puede ser lo que Vice hizo, ¿verdad?</size>",
  ui_story_5057_50571001_57_dialog_content = "<size=30>Ayer recordé que ella preguntaba dónde podía cocinar...</size>",
  ui_story_5057_50571001_58_dialog_content = "Oye, ¿qué estás murmurando?",
  ui_story_5057_50571001_59_dialog_content = "¿No tienes hambre? ¿No quieres comer conmigo?",
  ui_story_5057_50571001_60_dialog_content = "(Oh-oh, ¿ya es hora de tomar una decisión?)",
  ui_story_5057_50571001_61_dialog_content = "yo, eh...",
  ui_story_5057_50571001_62_option_content = "¡No puedo esperar para probar lo que hiciste, Vice!",
  ui_story_5057_50571001_63_dialog_content = "<size=30>Dado que no rechacé la primera vez que ella cocinó algo...</size>",
  ui_story_5057_50571001_64_dialog_content = "<size=30>¡Es mi responsabilidad comer cada comida Vice hecha!</size>",
  ui_story_5057_50571001_65_dialog_content = "Agradezco que me hayas susurrado la charla motivacional, pero hoy no preparé almuerzo.",
  ui_story_5057_50571001_66_dialog_content = "Ya que me levanté temprano en la mañana recolectando herramientas, ¡merecíamos darnos un capricho!",
  ui_story_5057_50571001_67_option_content = "¡Hoy corre por mi cuenta!",
  ui_story_5057_50571001_68_dialog_content = "¡Este es un parque, lo sabes! ¡Permíteme invitarte al restaurante que mencioné la última vez!",
  ui_story_5057_50571001_69_dialog_content = "Eso suena bien... Pero, ¿tienes el dinero, PlayerName?",
  ui_story_5057_50571001_70_dialog_content = "Eh, bueno... ¿Qué tal si me das un adelanto?",
  ui_story_5057_50571001_71_dialog_content = "¡Lo sabía!",
  ui_story_5057_50571001_72_dialog_content = "Vamos, de todos modos, tenía planeado usar el pago de este trabajo de mantenimiento para derrochar contigo.",
  ui_story_5057_50571001_73_dialog_content = "<color=#e8d9bb>Entonces Vice y yo pasamos un día lleno de alegría juntos, y ella se ve increíblemente feliz. ¡Eso es fantástico!</color>",
  ui_story_5057_50571002_1_dialog_content = "¡Aquí estamos!",
  ui_story_5057_50571002_2_dialog_content = "Bonita vista. Sería genial para acampar.",
  ui_story_5057_50571002_3_dialog_content = "Ayúdame, V-Vice... Mis rodillas están cediendo... bajo todo el equipo...",
  ui_story_5057_50571002_4_dialog_content = "¡PlayerName!",
  ui_story_5057_50571002_5_dialog_content = "¿Están bien? Vengan, siéntense y relájense.",
  ui_story_5057_50571002_6_dialog_content = "Estoy bien... Digo, yo fui el que te pidió que me enseñaras sobre supervivencia en la naturaleza después de todo...",
  ui_story_5057_50571002_7_dialog_content = "Así que debo esforzarme para llegar hasta el final...!",
  ui_story_5057_50571002_8_dialog_content = "¡Pero la carga es en realidad... demasiado pesada!",
  ui_story_5057_50571002_9_dialog_content = "Jajaja, lo lamento.",
  ui_story_5057_50571002_10_dialog_content = "Empacó raciones para diez días y todo el equipo necesario para el entrenamiento de supervivencia en la naturaleza para novatos de Illumina, así que probablemente esté un poco pesado.",
  ui_story_5057_50571002_11_dialog_content = "¿P-Por qué diez días? ¿Es realmente necesario?",
  ui_story_5057_50571002_12_dialog_content = "Bueno, cómo debería decirlo...",
  ui_story_5057_50571002_13_dialog_content = "Mayserá que la determinación en tus ojos anoche avivó el espíritu de lucha en mí.",
  ui_story_5057_50571002_14_dialog_content = "Fuiste tú quien dijo: \"Por favor, capacíteme, teniente Vice!\"",
  ui_story_5057_50571002_15_dialog_content = "Estaba reflexionando sobre tus limitaciones físicas mientras sacaba y volvía a guardar las raciones repetidamente.",
  ui_story_5057_50571002_16_dialog_content = "Teniendo en cuenta que estamos perfeccionando tu cuerpo y voluntad al máximo, decidí establecer la cantidad para diez días.",
  ui_story_5057_50571002_17_dialog_content = "Sin embargo, creo que podrías hacerlo, ¡y lo hiciste!",
  ui_story_5057_50571002_18_dialog_content = "Lamento que tengas una expectativa tan alta de mí.",
  ui_story_5057_50571002_19_dialog_content = "Afortunadamente, logré llevarlo todo hasta aquí y no te decepcioné.",
  ui_story_5057_50571002_20_dialog_content = "Sí, lo hiciste bien, PlayerName.",
  ui_story_5057_50571002_21_dialog_content = "Caminar tan lejos con esa carga es encomiable para un novato de Illumina.",
  ui_story_5057_50571002_22_dialog_content = "¿En serio?",
  ui_story_5057_50571002_23_dialog_content = "S-Sí...",
  ui_story_5057_50571002_24_dialog_content = "...",
  ui_story_5057_50571002_25_dialog_content = "Oh, debes estar exhausto, PlayerName. ¿Quieres tomar un descanso?",
  ui_story_5057_50571002_26_dialog_content = "Pon la mochila en el suelo y déjame masajear tus hombros.",
  ui_story_5057_50571002_27_dialog_content = "¿O deberíamos armar la tienda primero?",
  ui_story_5057_50571002_28_option_content = "¡Los necesito a ambos!",
  ui_story_5057_50571002_29_dialog_content = "¿Qué voy a hacer contigo, PlayerName...",
  ui_story_5057_50571002_30_dialog_content = "Bien, llamaremos esto la recompensa por tu arduo trabajo!",
  ui_story_5057_50571002_31_option_content = "Arma la tienda de campaña primero.",
  ui_story_5057_50571002_32_dialog_content = "Sí, es mejor tener un lugar para descansar.",
  ui_story_5057_50571002_33_dialog_content = "Te enseñaré cómo colocarlo, PlayerName.",
  ui_story_5057_50571002_34_dialog_content = "Simplemente coloca las estacas aquí.",
  ui_story_5057_50571002_35_dialog_content = "Ven, PlayerName, clava las estacas en el suelo con todo lo que tienes.",
  ui_story_5057_50571002_36_dialog_content = "Asegúrate de que entren profundo y seguro.",
  ui_story_5057_50571002_37_dialog_content = "¡Copiado! ¡Lo tengo!",
  ui_story_5057_50571002_38_dialog_content = "¡Heeyeah!",
  ui_story_5057_50571002_39_dialog_content = "¡Hiya!",
  ui_story_5057_50571002_40_dialog_content = "Eso servirá. Ahora coloca la lona sobre la tienda. Ya cubrí el suelo.",
  ui_story_5057_50571002_41_dialog_content = "Recuerda cubrir el suelo primero la próxima vez, PlayerName.",
  ui_story_5057_50571002_42_dialog_content = "¡Entendido!",
  ui_story_5057_50571002_43_dialog_content = "Cuando hayas terminado, prueba para ver si resiste.",
  ui_story_5057_50571002_44_dialog_content = "La tienda está completada si no hay problema.",
  ui_story_5057_50571002_45_dialog_content = "Déjame ver la tienda que construiste...",
  ui_story_5057_50571002_46_dialog_content = "Muy resistente. Sacarías 80 o más en una prueba.",
  ui_story_5057_50571002_47_dialog_content = "Ya te enseñé cómo leer el mapa y la brújula, así como explicar los pasos vitales de primeros auxilios.",
  ui_story_5057_50571002_48_dialog_content = "Sí, lo memoricé tanto como pude.",
  ui_story_5057_50571002_49_dialog_content = "Lo siguiente es la conservación de alimentos y agua, luego tendrás más del 70% de posibilidades de sobrevivir en la naturaleza.",
  ui_story_5057_50571002_50_dialog_content = "Tengo la sensación de que este Vice aquí y ahora ha salvado al futuro yo de nuevo.",
  ui_story_5057_50571002_51_dialog_content = "La tienda sí se siente bien, como si acabara de construir una casa para Vice y para mí.",
  ui_story_5057_50571002_52_dialog_content = "¿Oh sí? Entonces eso significa que somos familia, PlayerName?",
  ui_story_5057_50571002_53_dialog_content = "Por supuesto que eres familia, Vice.",
  ui_story_5057_50571002_54_dialog_content = "¿D-De verdad...?",
  ui_story_5057_50571002_55_dialog_content = "En realidad, yo también me siento así.",
  ui_story_5057_50571002_56_dialog_content = "Sí, es realmente genial pasar tiempo con la familia.",
  ui_story_5057_50571002_57_dialog_content = "Estoy muy feliz cuando estoy contigo.",
  ui_story_5057_50571002_58_dialog_content = "¡Oh, para agradecerte por el masaje y enseñarme a construir una tienda, cocinaré esta noche!",
  ui_story_5057_50571002_59_dialog_content = "Rogué a Gram que me mostrara cómo hacer las raciones más sabrosas.",
  ui_story_5057_50571002_60_dialog_content = "Está bien, esta vez viviré de ti, PlayerName.",
  ui_story_5057_50571002_61_dialog_content = "Comiendo las deliciosas raciones que cocinas mientras disfrutas del paisaje natural...",
  ui_story_5057_50571002_62_dialog_content = "¡Todo el agotamiento de tomar un trabajo tras otro simplemente desaparece!",
  ui_story_5057_50571002_63_dialog_content = "Acampar es genial, ya veo.",
  ui_story_5057_50571002_64_dialog_content = "¡Déjamelo a mí! ¡Encenderé el fuego ahora!",
  ui_story_5057_50571002_65_dialog_content = "<color=#e8d9bb>Entonces Vice y yo nos llenamos tanto que pasamos la tarde tumbados, maravillándonos con las estrellas hasta que se hace bastante tarde, antes de regresar finalmente a la tienda.</color>",
  ui_story_5057_50571101_1_dialog_content = "¡Lo siento, llego tarde!",
  ui_story_5057_50571101_2_dialog_content = "No te preocupes, aún tienes dos minutos. Yo acabo de llegar también.",
  ui_story_5057_50571101_3_dialog_content = "De todos modos, ¿por qué estás vestido así?",
  ui_story_5057_50571101_4_dialog_content = "Oh, es un mono de mantenimiento que tomé prestado de Lorelei.",
  ui_story_5057_50571101_5_dialog_content = "Ya que es difícil lavar las manchas de grasa de la ropa regular.",
  ui_story_5057_50571101_6_dialog_content = "Pero recuerdo que pediste múltiples conjuntos del mismo atuendo más tarde.",
  ui_story_5057_50571101_7_dialog_content = "Oh, originalmente me lo dio Soroz, uno de los pocos disfraces raros que me quedan bien.",
  ui_story_5057_50571101_8_dialog_content = "Antes de eso... Cómo debería decirlo... A veces iba sin ropa.",
  ui_story_5057_50571101_9_dialog_content = "Ya veo. Puedo comenzar a entender por qué eres tan sentimental al respecto.",
  ui_story_5057_50571101_10_dialog_content = "Pero es solo uno... ¿Qué tal si te llevo a conseguir dos nuevos conjuntos, hechos a medida, en Lumopolis la próxima vez?",
  ui_story_5057_50571101_11_dialog_content = "Puedo presentarte al sastre. El Señor de la Ciudad dijo que ha estado sirviendo a mi familia durante más de treinta años.",
  ui_story_5057_50571101_12_dialog_content = "¿Atendiendo a tu familia? ¿No lo convertiría eso en un sastre increíble?",
  ui_story_5057_50571101_13_dialog_content = "Absolutamente, sin duda un rival para los mejores diseñadores en Harbor City.",
  ui_story_5057_50571101_14_dialog_content = "Eso también podría ser muy costoso...",
  ui_story_5057_50571101_15_dialog_content = "No estoy seguro de eso yo mismo.",
  ui_story_5057_50571101_16_dialog_content = "Pero creo que hay espacio en el presupuesto de Lumopolis dedicado a los atuendos para el Señor de la Ciudad y su familia.",
  ui_story_5057_50571101_17_dialog_content = "Una moda personalizada para ajustarse emite sensaciones completamente diferentes.",
  ui_story_5057_50571101_18_dialog_content = "¿En serio? No es de extrañar que pensara que todos tus atuendos te quedan perfectos...",
  ui_story_5057_50571101_19_dialog_content = "Apareciste tan elegante y hermosa como la luz de la luna...",
  ui_story_5057_50571101_20_dialog_content = "No pude evitar recordar un dicho de Longzhou que leí...",
  ui_story_5057_50571101_21_dialog_content = "Se muestra de una manera hermosa, solo para esconderse en la nube lo suficientemente pronto.",
  ui_story_5057_50571101_22_dialog_content = "Creo que eso lo describe bastante bien.",
  ui_story_5057_50571101_23_dialog_content = "Ejem, gracias por el cumplido, pero por favor, para.",
  ui_story_5057_50571101_24_dialog_content = "Oh, lo siento. Fue una exageración.",
  ui_story_5057_50571101_25_dialog_content = "¿Qué?",
  ui_story_5057_50571101_26_dialog_content = "Eh, es decir... De todas formas...",
  ui_story_5057_50571101_27_dialog_content = "Jejeje... Está bien.",
  ui_story_5057_50571101_28_dialog_content = "¿No tienes trabajo que hacer? ¿No deberíamos dejar de hablar?",
  ui_story_5057_50571101_29_dialog_content = "¡Así es, tengo que arreglar el Dragón de la Noche Blanca!",
  ui_story_5057_50571101_30_dialog_content = "Vaya, estoy tan alto aquí... Parece que estoy de pie en el cielo.",
  ui_story_5057_50571101_31_dialog_content = "A veces es realmente difícil ganar dinero.",
  ui_story_5057_50571101_32_dialog_content = "El freno del tercer carro está roto, PlayerName.",
  ui_story_5057_50571101_33_dialog_content = "Simplemente intercambiarlo debería funcionar.",
  ui_story_5057_50571101_34_dialog_content = "Vale, estaré allí enseguida—!",
  ui_story_5057_50571101_35_dialog_content = "Cuidado, cuidado...",
  ui_story_5057_50571101_36_dialog_content = "No mires hacia abajo...",
  ui_story_5057_50571101_37_dialog_content = "Toma mi mano, PlayerName.",
  ui_story_5057_50571101_38_dialog_content = "¡Seguro!",
  ui_story_5057_50571101_39_dialog_content = "Tuviste una mala experiencia con el paseo la última vez, pero ahora no tienes miedo a las alturas.",
  ui_story_5057_50571101_40_dialog_content = "Estar en lo alto y montarlo son dos cosas diferentes... Lo segundo es un infierno.",
  ui_story_5057_50571101_41_dialog_content = "De acuerdo, me encargaré de la prueba de estrés después.",
  ui_story_5057_50571101_42_dialog_content = "Estoy cambiando el disco de freno.",
  ui_story_5057_50571101_43_dialog_content = "<color=#e8d9bb>Unos minutos después</color>",
  ui_story_5057_50571101_44_dialog_content = "Deberias hacer eso.",
  ui_story_5057_50571101_45_dialog_content = "Me subiré para una prueba de manejo. Solo contrólalo con este dispositivo aquí, Carleen.",
  ui_story_5057_50571101_46_dialog_content = "¿Estás seguro? Maydebería ser yo el que monta.",
  ui_story_5057_50571101_47_dialog_content = "No te preocupes, si algo sucede, yo me encargaré de ello.",
  ui_story_5057_50571101_48_dialog_content = "De acuerdo, ten cuidado entonces.",
  ui_story_5057_50571101_49_dialog_content = "Estoy abrochado... ¡Vale, déjalo correr!",
  ui_story_5057_50571101_50_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_5057_50571101_51_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_5057_50571101_52_dialog_content = "Vaya, esta montaña rusa seguro es un demonio de la velocidad.",
  ui_story_5057_50571101_53_dialog_content = "Espera, ¿cómo es que va mucho más rápido de lo habitual?",
  ui_story_5057_50571101_54_dialog_content = "<color=#e8d9bb>¡Clang, clang!</color>",
  ui_story_5057_50571101_55_dialog_content = "¡¿Qué demonios...?!",
  ui_story_5057_50571101_56_dialog_content = "Detén el paseo, Carleen!",
  ui_story_5057_50571101_57_dialog_content = "<color=#e8d9bb>Chirridos—</color>",
  ui_story_5057_50571101_58_dialog_content = "¡Se ha activado el freno!",
  ui_story_5057_50571101_59_dialog_content = "¡Puedo ver que el cuarto carrito se ha estado balanceando desde aquí!",
  ui_story_5057_50571101_60_dialog_content = "¡Lo entiendo! ¡Debe ser un problema con el conector!",
  ui_story_5057_50571101_61_dialog_content = "¿Por qué te desabrochaste, PlayerName?!",
  ui_story_5057_50571101_62_dialog_content = "Tengo que arreglarlo ahora, ¡o toda la montaña rusa podría salirse del riel y lastimar a las personas en el suelo!",
  ui_story_5057_50571101_63_dialog_content = "¡Es muy peligroso!",
  ui_story_5057_50571101_64_dialog_content = "No te preocupes, dame un segundo para bajarlo y podemos hacer que se detenga por completo...",
  ui_story_5057_50571101_65_dialog_content = "<color=#e8d9bb>Hacer clic-</color>",
  ui_story_5057_50571101_66_dialog_content = "¡Lo hice!",
  ui_story_5057_50571101_67_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5057_50571101_68_dialog_content = "¡¡¡PlayerName!!!",
  ui_story_5057_50571101_69_dialog_content = "¿Q-Qué está pasando, me salí volando del juego?",
  ui_story_5057_50571101_70_dialog_content = "Estoy cayendo rápido... ¿Es esto lo último que veo, siempre?",
  ui_story_5057_50571101_71_dialog_content = "¡Toma mi mano, PlayerName!",
  ui_story_5057_50571101_72_dialog_content = "¿Carleen? ¡Seguro!",
  ui_story_5057_50571101_73_dialog_content = "Uf... Tengo suerte de que estés cerca, Carleen.",
  ui_story_5057_50571101_74_dialog_content = "Me salvaste de nuevo. EveSe rompió el cable de seguridad. Qué vergonzoso...",
  ui_story_5057_50571101_75_dialog_content = "Por supuesto que voy a ayudar en cuanto tenga la oportunidad cuando estés en peligro, PlayerName.",
  ui_story_5057_50571101_76_dialog_content = "Somos amigos cercanos, así que no me debes nada.",
  ui_story_5057_50571101_77_dialog_content = "Está bien, pero aún me siento fatal por eso.",
  ui_story_5057_50571101_78_dialog_content = "¿Qué hay para sentirse terrible?",
  ui_story_5057_50571101_79_option_content = "Que necesito seguir siendo salvado",
  ui_story_5057_50571101_80_option_content = "Me gustaría guardar Carleen también",
  ui_story_5057_50571101_81_dialog_content = "Me encantaría tener el poder de protegerte y salvarte, Carleen.",
  ui_story_5057_50571101_82_dialog_content = "Ya veo.",
  ui_story_5057_50571101_83_dialog_content = "Pero, ¿no me has salvado a mí, a otras personas e incluso a Lumopolis, muchas veces a tu manera?",
  ui_story_5057_50571101_84_dialog_content = "Bueno, pero eso no es lo mismo.",
  ui_story_5057_50571101_85_dialog_content = "Todo me da igual.",
  ui_story_5057_50571101_86_dialog_content = "Para mí, me has estado cuidando a tu manera y con tu propio esfuerzo.",
  ui_story_5057_50571101_87_dialog_content = "Si te preocupa tanto, ¿por qué no me invitas a ese helado de allá?",
  ui_story_5057_50571101_88_dialog_content = "¿Qué? Por supuesto... Oye, espera, mis rodillas aún están temblando...",
  ui_story_5057_50571101_89_dialog_content = "<color=#e8d9bb>Entonces Carleen y yo comemos mucho helado juntos, lo que me deja con un fuerte dolor de cabeza durante toda la noche.</color>",
  ui_story_5057_50571102_1_dialog_content = "No es un problema, no es un problema esta vez, seguro...",
  ui_story_5057_50571102_2_dialog_content = "Soy un noble de Lumopolis después de todo.",
  ui_story_5057_50571102_3_dialog_content = "Soy Carleen de Schwartz, hija de Daniel de Schwartz.",
  ui_story_5057_50571102_4_dialog_content = "A pesar del peligro, venceré con mi aguda espada.",
  ui_story_5057_50571102_5_dialog_content = "A pesar de las dificultades, resistiré con honor.",
  ui_story_5057_50571102_6_dialog_content = "C-Carleen?",
  ui_story_5057_50571102_7_dialog_content = "Por favor, concédeme la serenidad para mantener la calma en el caos y mostrar misericordia en el odio.",
  ui_story_5057_50571102_8_dialog_content = "Concédeme la fe para permanecer resuelto en la incertidumbre, indomable en la agitación.",
  ui_story_5057_50571102_9_dialog_content = "Concédeme la resiliencia para mantenerme firme en las adversidades, fuerte bajo presión.",
  ui_story_5057_50571102_10_dialog_content = "Y la amabilidad de mantenerse compasivo en medio de la apatía, esperanzado en la desesperación.",
  ui_story_5057_50571102_11_dialog_content = "Eh, Carleen?",
  ui_story_5057_50571102_12_dialog_content = "Uf...",
  ui_story_5057_50571102_13_dialog_content = "No te ves tan bien... ¿Qué tal si lo olvidamos?",
  ui_story_5057_50571102_14_dialog_content = "No es necesario probar todas las atracciones emocionantes.",
  ui_story_5057_50571102_15_dialog_content = "¡Hay otras atracciones seguras pero igual de divertidas!",
  ui_story_5057_50571102_16_dialog_content = "Por ejemplo, ese lindo tren pequeño por ahí. Podemos tomarlo y recorrer todo Denuo.",
  ui_story_5057_50571102_17_dialog_content = "Y el carrusel es muy bonito con las luces en la noche... ¿No te gusta montar a caballo, Carleen?",
  ui_story_5057_50571102_18_dialog_content = "Además de la rueda de la fortuna...",
  ui_story_5057_50571102_19_dialog_content = "No.",
  ui_story_5057_50571102_20_dialog_content = "Lo siento, pero esto tiene que ver con... muchas cosas.",
  ui_story_5057_50571102_21_dialog_content = "¿Es Vice uno de ellos?",
  ui_story_5057_50571102_22_dialog_content = "No negaré eso, pero eso no es todo...",
  ui_story_5057_50571102_23_dialog_content = "Ambos recibimos el mismo entrenamiento riguroso. ¡No hay razón por la que no pueda hacer lo que ella pudo!",
  ui_story_5057_50571102_24_dialog_content = "Sin mencionar con tú como testigo...",
  ui_story_5057_50571102_25_dialog_content = "De todos modos, ¡tengo que practicar hasta tener la compostura de un verdadero caballero!",
  ui_story_5057_50571102_26_dialog_content = "¡Primer objetivo, Dragón de la Noche Blanca!",
  ui_story_5057_50571102_27_dialog_content = "<color=#e8d9bb>El primer paseo en el Dragón de la Noche Blanca</color>",
  ui_story_5057_50571102_28_dialog_content = "Creo que mi cinta para la cabeza acaba de ser arrancada por el viento.",
  ui_story_5057_50571102_29_dialog_content = "¡Continúa!",
  ui_story_5057_50571102_30_dialog_content = "<color=#e8d9bb>El segundo paseo en el Dragón de la Noche Blanca</color>",
  ui_story_5057_50571102_31_dialog_content = "Me siento mareado... parece que el mundo está girando.",
  ui_story_5057_50571102_32_dialog_content = "¡De nuevo!",
  ui_story_5057_50571102_33_dialog_content = "<color=#e8d9bb>El tercer paseo en el Dragón de la Noche Blanca</color>",
  ui_story_5057_50571102_34_dialog_content = "Creo que un Eclipsite me acaba de golpear en el estómago... *arcada*",
  ui_story_5057_50571102_35_dialog_content = "Mmm... ¡Maldita sea!",
  ui_story_5057_50571102_36_dialog_content = "Carleen, ¿qué tal si cambiamos a la Matriz de Fantasía?",
  ui_story_5057_50571102_37_dialog_content = "Ya estás esforzándote mucho.",
  ui_story_5057_50571102_38_dialog_content = "B-Buena idea.",
  ui_story_5057_50571102_39_dialog_content = "Supongo que podemos contar esto... como aprobado.",
  ui_story_5057_50571102_40_dialog_content = "Segundo objetivo, Matriz de Fantasía.",
  ui_story_5057_50571102_41_dialog_content = "<color=#e8d9bb>Después de salir de la Matriz de Fantasía con Carleen</color>",
  ui_story_5057_50571102_42_dialog_content = "M-Mi corazón está completamente en mi garganta.",
  ui_story_5057_50571102_43_dialog_content = "No me siento tan mal como antes.",
  ui_story_5057_50571102_44_dialog_content = "¿No crees que sea \"tan malo\" ahora?",
  ui_story_5057_50571102_45_dialog_content = "Te estás esforzando demasiado... Tres veces más y probablemente moriré.",
  ui_story_5057_50571102_46_dialog_content = "Mientras aún me quede algo de energía, probemos Cielo Azul.",
  ui_story_5057_50571102_47_dialog_content = "¿No es mejor enfrentarse a un paseo que no pudiste manejar la última vez?",
  ui_story_5057_50571102_48_dialog_content = "...",
  ui_story_5057_50571102_49_dialog_content = "O podemos regresar y agarrar alimento, mientras mi estómago aún está intacto.",
  ui_story_5057_50571102_50_dialog_content = "No, ¡nunca!",
  ui_story_5057_50571102_51_dialog_content = "¡Estoy enfrentando Blue Sky seguro esta vez! Si me congelo, ¡empújame inmediatamente!",
  ui_story_5057_50571102_52_dialog_content = "¿Listo?",
  ui_story_5057_50571102_53_dialog_content = "P-Por favor, concédeme la fe para permanecer resuelto en la incertidumbre, indomable en la agitación.",
  ui_story_5057_50571102_54_option_content = "Agarra Carleen y salta",
  ui_story_5057_50571102_55_dialog_content = "¿Eh? PlayerName?",
  ui_story_5057_50571102_56_dialog_content = "Puaj-!",
  ui_story_5057_50571102_57_option_content = "Vamos a regresar",
  ui_story_5057_50571102_58_dialog_content = "¡De ninguna manera!",
  ui_story_5057_50571102_59_dialog_content = "¡Empújame como prometiste!",
  ui_story_5057_50571102_60_dialog_content = "¡Vale, no digas que no te advertí!",
  ui_story_5057_50571102_61_dialog_content = "Por favor, concédeme el—",
  ui_story_5057_50571102_62_dialog_content = "Puaj-!",
  ui_story_5057_50571102_63_dialog_content = "¿Estás bien, Carleen? Aquí, apóyate en mí.",
  ui_story_5057_50571102_64_dialog_content = "Gracias, PlayerName...",
  ui_story_5057_50571102_65_dialog_content = "Después de todo el saltar y balancearse, en realidad me siento refrescado ahora.",
  ui_story_5057_50571102_66_dialog_content = "¿Qué? ¿Entonces estás bien con el cielo azul? ¿No hay dolor ni molestias?",
  ui_story_5057_50571102_67_dialog_content = "Creo que estoy bien.",
  ui_story_5057_50571102_68_dialog_content = "Qué aguante maravilloso... No, mejor dicho, extremadamente impresionante.",
  ui_story_5057_50571102_69_dialog_content = "Pero tengo un poco de sed.",
  ui_story_5057_50571102_70_dialog_content = "Vamos a tomar un poco de agua. No hemos bebido ni un sorbo porque no queríamos que nos subiera.",
  ui_story_5057_50571102_71_dialog_content = "Oh, veo un grifo para beber por ahí.",
  ui_story_5057_50571102_72_dialog_content = "¿Eh? ¡Espera, aguanta!",
  ui_story_5057_50571102_73_dialog_content = "Puaj-!",
  ui_story_5057_50571102_74_dialog_content = "Sí, todavía está roto... La última vez también me roció agua por todas partes.",
  ui_story_5057_50571102_75_dialog_content = "Vaya, tenemos que ir a cambiarnos.",
  ui_story_5057_50571102_76_dialog_content = "Aquí, cúbrete con mi ropa.",
  ui_story_5057_50571102_77_dialog_content = "Está bien, soy lo suficientemente fuerte como para no enfermarme tan fácilmente.",
  ui_story_5057_50571102_78_dialog_content = "... Pensándolo bien, olvida lo que dije. Gracias.",
  ui_story_5057_50571102_79_dialog_content = "Eh, ¿qué está pasando?",
  ui_story_5057_50571102_80_dialog_content = "Se siente bien apoyarse en ti de vez en cuando.",
  ui_story_5057_50571102_81_dialog_content = "Regresemos.",
  ui_story_5057_50571102_82_dialog_content = "<color=#e8d9bb>Después de que Carleen cambia su ropa, salimos y jugamos juntos en el carrusel y la rueda del cielo.</color>",
  ui_story_5057_50570002_1_dialog_content = "¡PlayerName!",
  ui_story_5057_50570002_2_dialog_content = "¡Oh, hola, Lorelei! ¿Qué te trae por aquí?",
  ui_story_5057_50570002_3_dialog_content = "Estoy en camino para verificar el estado de funcionamiento de los juegos mecánicos.",
  ui_story_5057_50570002_4_dialog_content = "No necesitas preocuparte por eso, PlayerName.",
  ui_story_5057_50570002_5_dialog_content = "Cena ya ha inspeccionado todo con la tripulación.",
  ui_story_5057_50570002_6_dialog_content = "Ya veo... Supongo que visitaré la ecozona y veré cómo están nuestras adorables criaturas.",
  ui_story_5057_50570002_7_dialog_content = "Bueno, en realidad, Vic está cuidando de ellos.",
  ui_story_5057_50570002_8_dialog_content = "¿En serio? ¿Qué pasa con la lista de los nuevos productos que llegan al distrito comercial?",
  ui_story_5057_50570002_9_dialog_content = "Tenemos a Vice y Carleen encargándose de eso también.",
  ui_story_5057_50570002_10_dialog_content = "Mmm... Recuerdo que dijiste que no había mucho espacio para mejoras en el área del hotel la última vez, ¿cierto?",
  ui_story_5057_50570002_11_dialog_content = "Sí, puedes relajarte ahora, PlayerName. No hace falta más esfuerzo extra.",
  ui_story_5057_50570002_12_dialog_content = "Gracias a tu ayuda, el complejo Denuo Valley Resort ahora está lleno de una increíble energía.",
  ui_story_5057_50570002_13_dialog_content = "Como el héroe detrás de la creación de este mundo maravilloso y mi asistente estrella, es hora de que tomes un descanso y disfrutes de los frutos de tu arduo trabajo.",
  ui_story_5057_50570002_14_dialog_content = "¡Aqui tienes!",
  ui_story_5057_50570002_15_dialog_content = "¿Mm...?",
  ui_story_5057_50570002_16_dialog_content = "He preparado esto especialmente para ti, un pase exclusivo para honrar a aquellos que han hecho contribuciones notables al Denuo Valley Resort.",
  ui_story_5057_50570002_17_dialog_content = "¡Es un privilegio único e inigualable!",
  ui_story_5057_50570002_18_dialog_content = "Con esta tarjeta, podrás disfrutar del resort sin problemas de boletos ni esperar en fila.",
  ui_story_5057_50570002_19_dialog_content = "¡Impresionante!",
  ui_story_5057_50570002_20_dialog_content = "Entonces, adelante y aprovecha al máximo tus merecidas vacaciones.",
  ui_story_5057_50570002_21_dialog_content = "Vendré a pasar tiempo contigo a menudo para divertirnos."
}
return config
